// 8개월차 (Day 211~240) · ep 37,38,39,40,41,42,43
window.JJ_DAYS = Object.assign(window.JJ_DAYS || {}, {"211":{"day":211,"ep":"37","epTitle":"赫鱗","epTitleKo":"혁린","title":"〜としても — ~라고 해도","watch":"37화 전반부 · 시부야역 화장실, 쵸소와 이타도리의 대치","scene":"죽은 동생 에소·케치즈의 원수를 갚으려고 쵸소가 이타도리 앞에 나타난다. 이타도리는 피를 쏘는 원거리 공격을 피하려고 싸움을 좁은 화장실 안으로 끌고 들어간다. 쵸소는 상대가 무엇을 노리든 동생들의 원수를 반드시 갚겠다고 다짐한다.","lines":[{"who":"쵸소","ja":"お前が謝ったとしても、弟たちは戻らない。","kana":"おまえが あやまったと しても、おとうとたちは もどらない。","ko":"네가 사과한다 해도 동생들은 돌아오지 않아."},{"who":"이타도리","ja":"狭い場所なら、撃たれたとしても近づける。","kana":"せまい ばしょなら、うたれたと しても ちかづける。","ko":"좁은 곳이라면 공격을 받는다 해도 다가갈 수 있어."},{"who":"쵸소","ja":"相手が誰だとしても、俺は兄として許さない。","kana":"あいてが だれだと しても、おれは あにと して ゆるさない。","ko":"상대가 누구라 해도 난 형으로서 용서 못 해."}],"words":[{"w":"復讐","r":"ふくしゅう","ko":"복수"},{"w":"犯罪","r":"はんざい","ko":"범죄"},{"w":"被害者","r":"ひがいしゃ","ko":"피해자"},{"w":"内側","r":"うちがわ","ko":"안쪽"},{"w":"証言","r":"しょうげん","ko":"증언"},{"w":"外側","r":"そとがわ","ko":"바깥쪽"},{"w":"動機","r":"どうき","ko":"동기"},{"w":"損","r":"そん","ko":"손해"}],"grammar":{"point":"〜としても","desc":"〜としても는 '설령 ~라고 해도'라는 가정의 역접입니다. 실제로 일어날지 모르는 일을 가정하고, 그래도 결과는 바뀌지 않는다고 말할 때 씁니다. 동사·い형용사 보통형에 그대로 붙이고(行くとしても・高いとしても), 명사·な형용사는 だ를 넣습니다(学生だとしても). 한국어 '~라고 해도', '~한다 치더라도'와 거의 같습니다.","ex":[{"ja":"今から出発するとしても、会議には間に合いません。","kana":"いまから しゅっぱつ すると しても、かいぎには まにあいません。","ko":"지금 출발한다 해도 회의에는 늦습니다."},{"ja":"保険料が少し高いとしても、保障が大切だと思います。","kana":"ほけんりょうが すこし たかいと しても、ほしょうが たいせつだと おもいます。","ko":"보험료가 조금 비싸다 해도 보장이 중요하다고 생각합니다."}]},"convert":{"anime":"てめえが何言ったとしても、関係ねえよ。","real":"どのようなご事情があったとしても、規則は変更できかねます。","note":"てめえ·関係ねえ는 매우 거친 반말입니다. 업무에서는 ご事情(사정)과 〜かねます(~하기 어렵습니다)로 정중하게 거절합니다."},"mission":"고객이 '지금 가입 안 해도 나중에 하면 되죠?'라고 묻습니다. 〜としても를 써서 늦게 가입할 때의 단점을 설명해 보세요.","missionEx":{"ja":"後で加入するとしても、保険料は今より高くなります。","kana":"あとで かにゅう すると しても、ほけんりょうは いまより たかく なります。","ko":"나중에 가입한다 해도 보험료는 지금보다 비싸집니다."},"quiz":[{"q":"「지금 출발한다 해도 늦는다」로 알맞은 것은?","choices":["今出発したら、間に合わない。","今出発するとしても、間に合わない。","今出発するので、間に合わない。"],"a":1,"why":"가정한 일을 해도 결과가 바뀌지 않으므로 〜としても를 씁니다."},{"q":"명사에 としても를 붙인 올바른 형태는?","choices":["学生だとしても","学生なとしても","学生のとしても"],"a":0,"why":"명사·な형용사는 だ를 넣어 〜だとしても가 됩니다."},{"q":"「動機」의 뜻은?","choices":["증언","피해","동기"],"a":2,"why":"動機(どうき)는 어떤 일을 하게 된 '동기'입니다. 범죄 뉴스에서 자주 나옵니다."}]},"212":{"day":212,"ep":"37","epTitle":"赫鱗","epTitleKo":"혁린","title":"〜にしても — ~하더라도, ~든 ~든","watch":"37화 중반부 · 화장실 안 근접전과 쵸소의 술식","scene":"좁은 공간에서 이타도리가 거리를 좁히자, 쵸소는 피를 압축해 쏘는 기술과 몸을 강화하는 기술로 맞선다. 두 사람 모두 상대의 수를 읽으며 한 치도 물러서지 않는다. 쵸소는 이타도리가 이 장소를 고른 데에 이유가 있다는 것을 깨닫는다.","lines":[{"who":"쵸소","ja":"偶然にしても、ここを選んだのは正しいな。","kana":"ぐうぜんに しても、ここを えらんだのは ただしいな。","ko":"우연이라 해도 여길 고른 건 옳았군."},{"who":"이타도리","ja":"遠くから撃つにしても、ここじゃ限界があるだろ。","kana":"とおくから うつに しても、ここじゃ げんかいが あるだろ。","ko":"멀리서 쏘더라도 여기선 한계가 있겠지."},{"who":"쵸소","ja":"近づくにしても、速度では俺のほうが上だ。","kana":"ちかづくに しても、そくどでは おれの ほうが うえだ。","ko":"다가오더라도 속도는 내가 위다."}],"words":[{"w":"偶然","r":"ぐうぜん","ko":"우연"},{"w":"臨時","r":"りんじ","ko":"임시"},{"w":"再開","r":"さいかい","ko":"재개"},{"w":"復旧","r":"ふっきゅう","ko":"복구"},{"w":"速度","r":"そくど","ko":"속도"},{"w":"運行","r":"うんこう","ko":"운행"},{"w":"時間帯","r":"じかんたい","ko":"시간대"},{"w":"路線","r":"ろせん","ko":"노선"}],"grammar":{"point":"〜にしても","desc":"〜にしても는 '~라고 해도', '~하더라도'라는 뜻으로 としても와 비슷하지만 회화에서 더 자주 쓰입니다. 상대의 사정을 일단 인정하면서 '그래도 ~'라고 덧붙일 때 편리합니다. 동사·い형용사 보통형, 명사에 바로 붙습니다(行くにしても・冗談にしても). 〜にしても〜にしても 꼴로 'A든 B든'이라는 뜻도 됩니다(行くにしても行かないにしても).","ex":[{"ja":"遅れるにしても、一言連絡をください。","kana":"おくれるに しても、ひとこと れんらくを ください。","ko":"늦더라도 한마디 연락을 주세요."},{"ja":"参加するにしてもしないにしても、金曜日までに返事をお願いします。","kana":"さんか するに しても しないに しても、きんようびまでに へんじを おねがい します。","ko":"참가하든 안 하든 금요일까지 답장 부탁드립니다."}]},"convert":{"anime":"冗談にしても、笑えねえぞ。","real":"ご冗談にしても、少し困ってしまいます。","note":"笑えねえ는 笑えない의 거친 남성 축약입니다. 업무 자리에서는 ご冗談과 困ってしまいます로 불편함을 부드럽게 전합니다."},"mission":"동료가 '이번 고객 미팅에 늦을 것 같아요'라고 합니다. 〜にしても로 부탁해 보세요.","missionEx":{"ja":"遅れるにしても、お客様に先に連絡してください。","kana":"おくれるに しても、おきゃくさまに さきに れんらく して ください。","ko":"늦더라도 고객님께 먼저 연락해 주세요."},"quiz":[{"q":"「참가하든 안 하든」을 일본어로?","choices":["参加するのにしないのに","参加するからしないから","参加するにしてもしないにしても"],"a":2,"why":"〜にしても〜にしても는 'A든 B든'이라는 뜻입니다."},{"q":"遅れる（　）、連絡をください。 빈칸에 알맞은 것은?","choices":["にしても","のに","から"],"a":0,"why":"'늦더라도 연락 주세요'이므로 にしても가 맞습니다."},{"q":"「速度」의 읽는 법은?","choices":["はやど","そくど","そくたく"],"a":1,"why":"速度는 そくど로 읽고 '속도'라는 뜻입니다."}]},"213":{"day":213,"ep":"37","epTitle":"赫鱗","epTitleKo":"혁린","title":"たとえ〜ても — 설령 ~하더라도","watch":"37화 후반부 · 쵸소의 강화된 공격과 쓰러지는 이타도리","scene":"쵸소는 피의 힘으로 몸을 강화해 이타도리를 몰아붙이고, 이타도리는 몇 번이나 큰 타격을 입는다. 그래도 이타도리는 다시 일어나 싸움을 이어 가지만, 결국 힘이 다해 의식을 잃고 쓰러진다.","lines":[{"who":"이타도리","ja":"たとえ骨が折れても、ここで倒れるわけにはいかない。","kana":"たとえ ほねが おれても、ここで たおれる わけには いかない。","ko":"설령 뼈가 부러져도 여기서 쓰러질 수는 없어."},{"who":"쵸소","ja":"たとえ何度立ち上がっても、結果は同じだ。","kana":"たとえ なんど たちあがっても、けっかは おなじだ。","ko":"몇 번을 일어선다 해도 결과는 같다."},{"who":"이타도리","ja":"たとえ勝てなくても、時間だけは稼いでみせる。","kana":"たとえ かてなくても、じかんだけは かせいで みせる。","ko":"설령 못 이기더라도 시간만큼은 벌어 보이겠어."}],"words":[{"w":"骨","r":"ほね","ko":"뼈"},{"w":"折れる","r":"おれる","ko":"부러지다, 꺾이다"},{"w":"揺れる","r":"ゆれる","ko":"흔들리다"},{"w":"壊れる","r":"こわれる","ko":"부서지다, 고장 나다"},{"w":"決して","r":"けっして","ko":"결코"},{"w":"出血","r":"しゅっけつ","ko":"출혈"},{"w":"手当て","r":"てあて","ko":"치료, 응급처치"},{"w":"息切れ","r":"いきぎれ","ko":"숨이 참"}],"grammar":{"point":"たとえ〜ても","desc":"たとえ〜ても는 '설령 ~하더라도'라는 뜻으로, 〜ても(~해도) 앞에 たとえ를 붙여 '아무리 극단적인 경우라도'라는 강한 의지나 단정을 나타냅니다. 동사·い형용사는 て형+も(行っても・高くても), 명사·な형용사는 でも(雨でも・大変でも)가 됩니다. 한국어 '설령/비록 ~라도'와 같고, 뒤에는 결심이나 변하지 않는 사실이 자주 옵니다.","ex":[{"ja":"たとえ失敗しても、もう一度挑戦します。","kana":"たとえ しっぱい しても、もう いちど ちょうせん します。","ko":"설령 실패하더라도 한 번 더 도전하겠습니다."},{"ja":"たとえ家族に反対されても、この仕事を続けたいです。","kana":"たとえ かぞくに はんたい されても、この しごとを つづけたいです。","ko":"설령 가족이 반대해도 이 일을 계속하고 싶습니다."}]},"convert":{"anime":"たとえ死んでも、絶対に引かねえ。","real":"たとえ難しくても、決して途中で諦めません。","note":"引かねえ는 引かない의 거친 반말입니다. 업무에서는 死んでも 같은 과격한 말 대신 難しくても, 決して〜ません으로 각오를 정중하게 표현합니다."},"mission":"올해 꼭 이루고 싶은 목표를 たとえ〜ても로 말해 보세요. (예: 일본어 공부, 영업 목표, 건강 관리)","missionEx":{"ja":"たとえ忙しくても、毎日日本語を三十分勉強します。","kana":"たとえ いそがしくても、まいにち にほんごを さんじゅっぷん べんきょう します。","ko":"설령 바빠도 매일 일본어를 30분 공부하겠습니다."},"quiz":[{"q":"「설령 비가 와도 갑니다」로 알맞은 것은?","choices":["たとえ雨なら、行きます。","たとえ雨が降るので、行きます。","たとえ雨が降っても、行きます。"],"a":2,"why":"たとえ는 〜ても와 짝을 이룹니다."},{"q":"たとえ 뒤에 짝으로 오는 형태는?","choices":["〜から","〜ても / 〜でも","〜ので"],"a":1,"why":"たとえ〜ても(でも)로 '설령 ~라도'가 됩니다."},{"q":"「骨」의 뜻은?","choices":["뼈","피","상처"],"a":0,"why":"骨(ほね)는 '뼈'입니다."}]},"214":{"day":214,"ep":"37","epTitle":"赫鱗","epTitleKo":"혁린","title":"〜からといって — ~라고 해서 (꼭 ~은 아니다)","watch":"37화 마지막 · 쵸소가 본 존재하지 않는 기억","scene":"쓰러진 이타도리에게 마지막 공격을 하려던 순간, 쵸소의 머릿속에 이타도리와 형제들이 함께 식탁에 둘러앉은 본 적 없는 기억이 흘러든다. 이길 수 있는 상황이었지만 쵸소는 크게 혼란스러워하며 공격을 멈추고 그 자리를 떠난다.","lines":[{"who":"쵸소","ja":"有利だからといって、最後まで油断はしない。","kana":"ゆうりだからと いって、さいごまで ゆだんは しない。","ko":"유리하다고 해서 끝까지 방심은 안 해."},{"who":"쵸소","ja":"こいつが俺の弟だなんて、そんなはずはない…。","kana":"こいつが おれの おとうとだ なんて、そんな はずは ない…。","ko":"이 녀석이 내 동생이라니, 그럴 리가 없어…."},{"who":"쵸소","ja":"勝ったからといって、心は少しも晴れないな…。","kana":"かったからと いって、こころは すこしも はれないな…。","ko":"이겼다고 해서 마음이 조금도 개운하지 않군…."}],"words":[{"w":"有利","r":"ゆうり","ko":"유리"},{"w":"警報","r":"けいほう","ko":"경보"},{"w":"防災","r":"ぼうさい","ko":"방재, 재해 대비"},{"w":"地震","r":"じしん","ko":"지진"},{"w":"避難所","r":"ひなんじょ","ko":"대피소"},{"w":"災害","r":"さいがい","ko":"재해"},{"w":"値段","r":"ねだん","ko":"가격"},{"w":"損害","r":"そんがい","ko":"손해"}],"grammar":{"point":"〜からといって","desc":"〜からといって는 '~라고 해서'라는 뜻으로, 뒤에 '반드시 ~인 것은 아니다'라는 부정이 옵니다. 어떤 이유 하나만으로 당연히 그렇다고 판단하면 안 된다고 말할 때 씁니다. 보통형에 붙고(高いからといって・学生だからといって), 뒤에는 〜わけではない, 〜とは限らない, 〜てはいけない 등이 자주 옵니다. 회화에서는 〜からって로 줄여 말하기도 합니다.","ex":[{"ja":"値段が高いからといって、いい商品だとは限りません。","kana":"ねだんが たかいからと いって、いい しょうひんだとは かぎりません。","ko":"가격이 비싸다고 해서 좋은 상품이라고는 할 수 없습니다."},{"ja":"若いからといって、保険が必要ないわけではありません。","kana":"わかいからと いって、ほけんが ひつよう ない わけでは ありません。","ko":"젊다고 해서 보험이 필요 없는 것은 아닙니다."}]},"convert":{"anime":"勝ったからって、調子に乗んなよ。","real":"契約が取れたからといって、油断しないようにしましょう。","note":"〜からって는 からといって의 회화 축약이고, 調子に乗んな는 '까불지 마'라는 거친 명령입니다. 팀원에게는 〜ないようにしましょう로 함께 조심하자고 말합니다."},"mission":"고객이 '저는 건강하니까 보험은 필요 없어요'라고 합니다. 〜からといって로 답해 보세요.","missionEx":{"ja":"今健康だからといって、将来も安心とは限りません。","kana":"いま けんこうだからと いって、しょうらいも あんしんとは かぎりません。","ko":"지금 건강하다고 해서 앞으로도 안심이라고는 할 수 없습니다."},"quiz":[{"q":"〜からといって 뒤에 자주 오는 표현은?","choices":["〜てください","〜ましょう","〜とは限らない"],"a":2,"why":"'~라고 해서 꼭 ~인 것은 아니다'라는 부정 표현이 뒤따릅니다."},{"q":"「젊다고 해서 보험이 필요 없는 건 아니다」로 알맞은 것은?","choices":["若いので、保険は必要ないです。","若いからといって、保険が必要ないわけではない。","若いのに、保険が必要です。"],"a":1,"why":"〜からといって〜わけではない로 단정을 부정합니다."},{"q":"「警報」의 뜻은?","choices":["경보","유리","재해"],"a":0,"why":"警報(けいほう)는 위험을 알리는 '경보'입니다."}]},"215":{"day":215,"ep":"38","epTitle":"揺蕩","epTitleKo":"요탕","title":"〜ものだ — 원래 ~하는 법이다 / ~하곤 했다","watch":"38화 전반부 · 혼란에 빠진 쵸소와 형제의 기억","scene":"싸움터를 떠난 쵸소는 방금 머릿속에 떠오른 기억이 무엇이었는지 곱씹는다. 주태구상도 형제의 맏형으로서 동생들을 지키는 것이 자신의 존재 이유라고 믿어 온 쵸소는, 이타도리도 자신의 동생일지 모른다는 생각에 크게 흔들린다.","lines":[{"who":"쵸소","ja":"兄というものは、いつも弟を守るものだ。","kana":"あにと いう ものは、いつも おとうとを まもる ものだ。","ko":"형이란 언제나 동생을 지키는 법이다."},{"who":"쵸소","ja":"昔はよく、弟たちのことを考えたものだ。","kana":"むかしは よく、おとうとたちの ことを かんがえた ものだ。","ko":"예전엔 자주 동생들 생각을 하곤 했지."},{"who":"쵸소","ja":"あの記憶は、いったい何だったんだ…。","kana":"あの きおくは、いったい なんだったんだ…。","ko":"그 기억은 대체 뭐였지…."}],"words":[{"w":"記事","r":"きじ","ko":"기사"},{"w":"記者","r":"きしゃ","ko":"기자"},{"w":"番組","r":"ばんぐみ","ko":"방송 프로그램"},{"w":"放送","r":"ほうそう","ko":"방송"},{"w":"幼い","r":"おさない","ko":"어리다"},{"w":"親","r":"おや","ko":"부모"},{"w":"録画","r":"ろくが","ko":"녹화"},{"w":"画面","r":"がめん","ko":"화면"}],"grammar":{"point":"〜ものだ (당연·회상)","desc":"〜ものだ에는 두 가지 쓰임이 있습니다. ① 사전형+ものだ는 '원래 ~하는 법이다'라는 당연·상식입니다(人は変わるものだ, 사람은 변하는 법이다). ② た형+ものだ는 '(예전에) 자주 ~하곤 했다'라는 회상입니다(よく遊んだものだ). 회상일 때는 よく, 昔は, 子どもの頃は 같은 말과 함께 그리움이 담깁니다. 회화에서는 〜もんだ로 줄여 말하기도 합니다.","ex":[{"ja":"子どもは親が思うより早く成長するものです。","kana":"こどもは おやが おもうより はやく せいちょう する ものです。","ko":"아이는 부모가 생각하는 것보다 빨리 자라는 법입니다."},{"ja":"若い頃は、よく夜遅くまで仕事をしたものです。","kana":"わかい ころは、よく よる おそくまで しごとを した ものです。","ko":"젊었을 때는 자주 밤늦게까지 일을 하곤 했습니다."}]},"convert":{"anime":"ガキの頃はよく喧嘩したもんだ。","real":"子どもの頃は、よく兄弟げんかをしたものです。","note":"ガキ는 '꼬맹이'라는 거친 말이고 〜もんだ는 ものだ의 반말 축약입니다. 정중하게는 子どもの頃, 〜ものです로 말합니다."},"mission":"일본인 고객과 잡담하며 어린 시절 추억을 〜たものです로 이야기해 보세요.","missionEx":{"ja":"子どもの頃は、よく父と釣りに行ったものです。","kana":"こどもの ころは、よく ちちと つりに いった ものです。","ko":"어렸을 때는 자주 아버지와 낚시하러 가곤 했습니다."},"quiz":[{"q":"회상의 〜ものだ로 알맞은 것은?","choices":["昔はよく、この公園で遊ぶものだ。","昔はよく、この公園で遊んだものだ。","昔はよく、この公園で遊びたいものだ。"],"a":1,"why":"회상은 た형+ものだ입니다."},{"q":"「사람은 변하는 법이다」로 알맞은 것은?","choices":["人は変わったものだ。","人は変わるものか。","人は変わるものだ。"],"a":2,"why":"당연·상식은 사전형+ものだ입니다."},{"q":"「録画」의 뜻은?","choices":["녹화","화면","방송"],"a":0,"why":"録画(ろくが)는 영상을 기록하는 '녹화'입니다."}]},"216":{"day":216,"ep":"38","epTitle":"揺蕩","epTitleKo":"요탕","title":"〜ものの — ~하긴 했지만","watch":"38화 · 의식을 잃은 이타도리, 흔들리는 쵸소","scene":"쵸소는 싸움에서 이겼지만 끝내 마무리를 짓지 못한 채 떠났고, 이타도리는 그 자리에 쓰러져 의식을 잃었다. 시부야 곳곳에서는 다른 술사들도 각자의 싸움을 이어 가며 혼란은 점점 커진다.","lines":[{"who":"쵸소","ja":"勝ったものの、どうしても手が動かなかった。","kana":"かった ものの、どうしても てが うごかなかった。","ko":"이기긴 했지만 아무리 해도 손이 움직이지 않았다."},{"who":"쵸소","ja":"頭ではわかっているものの、心が混乱している。","kana":"あたまでは わかって いる ものの、こころが こんらん して いる。","ko":"머리로는 알지만 마음이 혼란스럽다."},{"who":"쵸소","ja":"理由はわからないものの、あいつには手を出せない。","kana":"りゆうは わからない ものの、あいつには てを だせない。","ko":"이유는 모르겠지만 그 녀석에겐 손을 댈 수 없다."}],"words":[{"w":"真相","r":"しんそう","ko":"진상"},{"w":"捜査","r":"そうさ","ko":"수사"},{"w":"発生","r":"はっせい","ko":"발생"},{"w":"取材","r":"しゅざい","ko":"취재"},{"w":"申請","r":"しんせい","ko":"신청"},{"w":"窓口","r":"まどぐち","ko":"창구"},{"w":"気絶","r":"きぜつ","ko":"기절"},{"w":"受付","r":"うけつけ","ko":"접수, 접수처"}],"grammar":{"point":"〜ものの","desc":"〜ものの는 '~하긴 했지만', '~이긴 하지만'이라는 역접입니다. 앞의 일은 사실로 인정하지만, 기대한 결과로 이어지지 않았다고 말할 때 씁니다. 동사·い형용사 보통형에 붙고, 명사·な형용사는 である를 넣어 〜であるものの로 씁니다. けれども보다 딱딱한 문어체 느낌이라 보고서·이메일 같은 업무 문장에 잘 어울립니다.","ex":[{"ja":"申し込んだものの、まだ準備が全然できていません。","kana":"もうしこんだ ものの、まだ じゅんびが ぜんぜん できて いません。","ko":"신청은 했지만 아직 준비가 전혀 안 됐습니다."},{"ja":"状況は理解したものの、結局その場では決められませんでした。","kana":"じょうきょうは りかい した ものの、けっきょく その ばでは きめられませんでした。","ko":"상황은 이해했지만 결국 그 자리에서는 정하지 못했습니다."}]},"convert":{"anime":"勝つには勝ったけどよ、スッキリしねえ。","real":"ご契約はいただいたものの、まだ課題が残っております。","note":"〜けどよ·しねえ는 거친 반말입니다. 보고할 때는 〜ものの로 성과를 인정하면서 남은 과제를 정중히 덧붙입니다."},"mission":"상사에게 '이번 달 목표 건수는 채웠지만 금액은 부족하다'고 〜ものの로 보고해 보세요.","missionEx":{"ja":"件数は達成したものの、金額はまだ目標に届いていません。","kana":"けんすうは たっせい した ものの、きんがくは まだ もくひょうに とどいて いません。","ko":"건수는 달성했지만 금액은 아직 목표에 미치지 못했습니다."},"quiz":[{"q":"「신청은 했지만 준비가 안 됐다」로 알맞은 것은?","choices":["申し込んだので、準備ができていない。","申し込んだものの、準備ができていない。","申し込むものだ、準備ができていない。"],"a":1,"why":"앞일은 인정하고 기대와 다른 결과를 말하므로 〜ものの입니다."},{"q":"명사에 ものの를 붙이는 형태는?","choices":["学生なものの","学生だものの","学生であるものの"],"a":2,"why":"명사·な형용사는 〜であるものの로 씁니다."},{"q":"「発生」의 뜻은?","choices":["발생","수사","진상"],"a":0,"why":"発生(はっせい)는 사건·사고의 '발생'입니다."}]},"218":{"day":218,"ep":"38","epTitle":"揺蕩","epTitleKo":"요탕","title":"〜ことだ — ~하는 게 제일이다 (충고)","watch":"38화 · 혼란 속에서 스스로를 다잡는 쵸소","scene":"쵸소가 떠난 뒤에도 시부야의 상황은 계속 나빠지고, 고전 술사들은 흩어진 채 저주사와 저주를 상대한다. 쵸소 역시 상처를 안은 채, 혼란스러운 마음을 가라앉히고 이타도리의 정체를 직접 확인해야겠다고 생각한다.","lines":[{"who":"쵸소","ja":"心が迷ったときは、まず静かに落ち着くことだ。","kana":"こころが まよった ときは、まず しずかに おちつく ことだ。","ko":"망설여질 땐 우선 침착해지는 게 먼저다."},{"who":"쵸소","ja":"答えが欲しければ、自分で確かめることだ。","kana":"こたえが ほしければ、じぶんで たしかめる ことだ。","ko":"답을 원한다면 스스로 확인하는 거다."},{"who":"쵸소","ja":"今は無理をせず、まずこの傷を治すことだな。","kana":"いまは むりを せず、まず この きずを なおす ことだな。","ko":"지금은 무리하지 말고 상처를 치료하는 게 먼저군."}],"words":[{"w":"消火","r":"しょうか","ko":"소화, 불을 끔"},{"w":"冷静","r":"れいせい","ko":"냉정, 침착"},{"w":"火事","r":"かじ","ko":"화재, 불"},{"w":"燃える","r":"もえる","ko":"타다, 불타다"},{"w":"点検","r":"てんけん","ko":"점검"},{"w":"睡眠","r":"すいみん","ko":"수면"},{"w":"医者","r":"いしゃ","ko":"의사"},{"w":"故障","r":"こしょう","ko":"고장"}],"grammar":{"point":"〜ことだ (충고)","desc":"〜ことだ는 '~하는 것이 제일이다', '~하는 게 좋다'라는 충고·조언입니다. 동사 사전형이나 ない형에 붙입니다(早く寝ることだ, 無理をしないことだ). 주로 윗사람이 아랫사람에게, 또는 일반적인 조언으로 쓰기 때문에 고객이나 상사에게 직접 쓰면 실례가 될 수 있습니다. 정중하게 조언할 때는 〜たほうがいいですよ를 쓰는 편이 안전합니다.","ex":[{"ja":"風邪を早く治したいなら、十分な睡眠をとることだ。","kana":"かぜを はやく なおしたいなら、じゅうぶんな すいみんを とる ことだ。","ko":"감기를 빨리 낫게 하고 싶으면 충분히 자는 게 제일이다."},{"ja":"自信がないときは、一人で悩まないで先輩に相談することだ。","kana":"じしんが ない ときは、ひとりで なやまないで せんぱいに そうだん する ことだ。","ko":"자신이 없을 때는 혼자 고민하지 말고 선배와 상담하는 게 좋다."}]},"convert":{"anime":"ビビってねえで、さっさと医者に行くことだな。","real":"ご無理なさらず、早めに病院で診てもらったほうがいいですよ。","note":"〜ことだ는 위에서 내려다보는 충고라 고객에게 쓰면 실례입니다. ビビる(쫄다)·さっさと도 거친 말이니, 〜たほうがいいですよ로 부드럽게 권합니다."},"mission":"신입 설계사 후배가 '첫 상담이 너무 긴장돼요'라고 합니다. 〜ことだ로 조언해 보세요.","missionEx":{"ja":"緊張したら、まずお客様の話をよく聞くことだよ。","kana":"きんちょう したら、まず おきゃくさまの はなしを よく きく ことだよ。","ko":"긴장되면 우선 고객님 이야기를 잘 듣는 게 제일이야."},"quiz":[{"q":"「무리하지 않는 게 좋다」로 알맞은 것은?","choices":["無理をしたことだ。","無理をしないことだ。","無理をしないものの。"],"a":1,"why":"충고의 〜ことだ는 사전형·ない형에 붙습니다."},{"q":"고객에게 조언할 때 더 알맞은 표현은?","choices":["早く寝ることだ。","早く寝たことか。","早く寝たほうがいいですよ。"],"a":2,"why":"〜ことだ는 윗사람이 하는 충고라, 고객에게는 〜たほうがいいですよ가 정중합니다."},{"q":"「睡眠」의 읽는 법은?","choices":["すいみん","ねむり","すいめん"],"a":0,"why":"睡眠은 すいみん으로 읽고 '수면'이라는 뜻입니다."}]},"219":{"day":219,"ep":"38","epTitle":"揺蕩","epTitleKo":"요탕","title":"〜ことか — 얼마나 ~했던가 (감탄)","watch":"38화 후반부 · 동생들을 향한 쵸소의 마음","scene":"쵸소는 오랜 세월 동생들과 함께해 온 시간과, 에소·케치즈를 잃은 슬픔을 떠올린다. 형으로서 동생들을 얼마나 아껴 왔는지 되새기며, 흔들리는 마음을 안고 이타도리에 대한 답을 찾으려 한다.","lines":[{"who":"쵸소","ja":"弟たちとの時間が、どれほど大切だったことか。","kana":"おとうとたちとの じかんが、どれほど たいせつだった ことか。","ko":"동생들과의 시간이 얼마나 소중했던가."},{"who":"쵸소","ja":"二人を失って、何度悔しい思いをしたことか。","kana":"ふたりを うしなって、なんど くやしい おもいを した ことか。","ko":"둘을 잃고 몇 번이나 분한 마음이 들었던가."},{"who":"쵸소","ja":"もし本当に弟なら、どんなに嬉しいことか…。","kana":"もし ほんとうに おとうとなら、どんなに うれしい ことか…。","ko":"만약 정말 동생이라면 얼마나 기쁠까…."}],"words":[{"w":"呼びかける","r":"よびかける","ko":"호소하다, 말을 걸다"},{"w":"通話","r":"つうわ","ko":"통화"},{"w":"着信","r":"ちゃくしん","ko":"착신, 전화가 옴"},{"w":"送信","r":"そうしん","ko":"송신, 보내기"},{"w":"留守番電話","r":"るすばんでんわ","ko":"자동응답 전화"},{"w":"苦しい","r":"くるしい","ko":"괴롭다"},{"w":"失う","r":"うしなう","ko":"잃다"},{"w":"願う","r":"ねがう","ko":"바라다, 빌다"}],"grammar":{"point":"〜ことか (감탄)","desc":"〜ことか는 '얼마나 ~했던가', '얼마나 ~한지 모른다'라는 강한 감탄입니다. 주로 どんなに・どれほど・何度 같은 말과 함께 쓰여 감정의 크기를 강조합니다. 보통형에 붙고, な형용사 현재형은 〜なことか(どんなに大切なことか)로 씁니다. 의문문처럼 보이지만 질문이 아니라 감정을 토로하는 말이며, 정중하게는 〜ことでしょう라고 합니다.","ex":[{"ja":"お客様からの感謝の手紙が、どんなに嬉しかったことか。","kana":"おきゃくさまからの かんしゃの てがみが、どんなに うれしかった ことか。","ko":"고객님의 감사 편지가 얼마나 기뻤는지 모릅니다."},{"ja":"合格の知らせを、家族みんなでどれほど喜んだことか。","kana":"ごうかくの しらせを、かぞく みんなで どれほど よろこんだ ことか。","ko":"합격 소식을 가족 모두가 얼마나 기뻐했는지 모릅니다."}]},"convert":{"anime":"マジで何回ムカついたことか。","real":"正直、何度悔しい思いをしたことでしょう。","note":"マジで·ムカつく는 젊은 층의 거친 속어입니다. 공적인 자리에서는 正直(솔직히)와 〜ことでしょう로 감정을 정중하고 차분하게 표현합니다."},"mission":"일본인 고객이 '오랜 준비 끝에 목표를 이루셨네요'라고 합니다. 〜ことか로 그 기쁨을 표현해 보세요.","missionEx":{"ja":"この日をどれほど待ったことか。本当にありがとうございます。","kana":"この ひを どれほど まった ことか。ほんとうに ありがとう ございます。","ko":"이날을 얼마나 기다렸는지 모릅니다. 정말 감사합니다."},"quiz":[{"q":"〜ことか와 함께 자주 쓰는 말은?","choices":["どんなに","だから","たとえ"],"a":0,"why":"どんなに・どれほど・何度 등과 함께 감정의 크기를 강조합니다."},{"q":"「얼마나 기뻤는지 모른다」로 알맞은 것은?","choices":["どんなに嬉しかったものの。","嬉しかったからといって。","どんなに嬉しかったことか。"],"a":2,"why":"감탄은 どんなに〜ことか입니다."},{"q":"「送信」의 뜻은?","choices":["수신","송신, 보내기","통화"],"a":1,"why":"送信(そうしん)은 메시지 등을 '보내기, 송신'입니다."}]},"220":{"day":220,"ep":"39","epTitle":"揺蕩-弐-","epTitleKo":"요탕 2","title":"~하면서 — 〜つつ","watch":"39화 · 되살아난 스쿠나 앞에 죠고가 찾아와 협력을 청하는 장면","scene":"강제로 손가락을 여러 개 삼킨 이타도리 대신 스쿠나가 몸을 차지한다. 죠고는 스쿠나에게 함께하자고 청하고, 스쿠나는 여유롭게 '한 방이라도 맞히면 생각해 보겠다'는 조건을 건다. 이렇게 두 특급의 싸움이 시작된다.","lines":[{"who":"죠고","ja":"あなたの復活を待ちつつ、我々は準備してきた。","kana":"あなたの ふっかつを まちつつ、われわれは じゅんび してきた。","ko":"당신의 부활을 기다리며 우리는 준비해 왔다."},{"who":"스쿠나","ja":"いいだろう。一撃でも当てれば、従ってやる。","kana":"いいだろう。いちげき でも あてれば、したがって やる。","ko":"좋다. 한 방이라도 맞히면 따라 주지."},{"who":"죠고","ja":"怖さを感じつつも、この機会は逃さない!","kana":"こわさを かんじつつも、この きかいは のがさない!","ko":"두려움을 느끼면서도 이 기회는 놓치지 않겠다!"}],"words":[{"w":"堂々と","r":"どうどうと","ko":"당당하게"},{"w":"挑戦","r":"ちょうせん","ko":"도전"},{"w":"見くびる","r":"みくびる","ko":"얕보다"},{"w":"一撃","r":"いちげき","ko":"일격, 한 방"},{"w":"格下","r":"かくした","ko":"한 수 아래"},{"w":"恐怖","r":"きょうふ","ko":"공포"},{"w":"威力","r":"いりょく","ko":"위력"},{"w":"見逃す","r":"みのがす","ko":"놓치다, 못 본 척하다"}],"grammar":{"point":"〜つつ","desc":"동사 ます형 어간 + つつ는 '~하면서'라는 뜻으로, ながら와 비슷하지만 글이나 격식 있는 자리에서 쓰는 딱딱한 표현입니다. 〜つつも가 되면 '~하면서도'라는 역접이 되어, 한국어의 '알면서도'처럼 마음과 행동이 엇갈릴 때 씁니다(知りつつも). 〜つつある는 '점점 ~하고 있다'는 변화의 진행을 나타냅니다(回復しつつある). 업무 메일이나 상담 멘트에서 ながら 대신 쓰면 한층 정중하게 들립니다.","ex":[{"ja":"お客様のご意見を伺いつつ、プランを作成いたします。","kana":"おきゃくさまの ごいけんを うかがいつつ、ぷらんを さくせい いたします。","ko":"고객님의 의견을 여쭈면서 플랜을 작성하겠습니다."},{"ja":"体に悪いと知りつつ、つい夜中に食べてしまいます。","kana":"からだに わるいと しりつつ、つい よなかに たべて しまいます。","ko":"몸에 나쁜 줄 알면서도 그만 한밤중에 먹어 버립니다."}]},"convert":{"anime":"一撃でも当ててみろ。","real":"一度試してみていただけますか。","note":"〜てみろ는 상대를 도발하는 명령형입니다. 업무에서는 〜てみてください, 더 정중하게는 〜てみていただけますか로 바꿉니다."},"mission":"상담 시작 전, 고객에게 '말씀을 들으면서 메모를 하겠다'고 양해를 구해 보세요.","missionEx":{"ja":"お話を伺いつつ、メモを取らせていただきます。","kana":"おはなしを うかがいつつ、めもを とらせて いただきます。","ko":"말씀을 들으면서 메모를 하겠습니다."},"quiz":[{"q":"「伺う」에 つつ를 붙인 올바른 형태는?","choices":["伺うつつ","伺いつつ","伺ってつつ"],"a":1,"why":"つつ는 ます형 어간(伺い)에 붙습니다."},{"q":"「悪いと知りつつ」의 뜻은?","choices":["나쁜 줄 알면서도","나쁜 줄 몰라서","나쁘다고 알려 주고"],"a":0,"why":"〜つつ(も)는 '~하면서도'라는 역접으로도 쓰입니다."},{"q":"「堂々と」의 읽는 법은?","choices":["とうとうと","どうとうと","どうどうと"],"a":2,"why":"堂々と는 どうどうと, '당당하게'라는 뜻입니다."}]},"221":{"day":221,"ep":"39","epTitle":"揺蕩-弐-","epTitleKo":"요탕 2","title":"~하면서도 — 〜ながらも","watch":"39화 · 죠고가 화염 술식을 퍼붓지만 스쿠나가 가볍게 받아넘기는 장면","scene":"죠고는 시부야 거리를 불바다로 만들 만큼 강력한 화염을 연달아 날린다. 하지만 스쿠나는 거의 움직이지 않고 받아넘기며 오히려 품평까지 한다. 죠고는 압도적인 실력 차를 느끼면서도 물러서지 않는다.","lines":[{"who":"죠고","ja":"押されながらも、私はまだ諦めていない!","kana":"おされながらも、わたしは まだ あきらめて いない!","ko":"밀리면서도 나는 아직 포기하지 않았다!"},{"who":"스쿠나","ja":"未熟ながらも、なかなか悪くない炎を出すな。","kana":"みじゅく ながらも、なかなか わるく ない ほのおを だすな。","ko":"미숙하긴 해도 꽤 나쁘지 않은 불꽃을 내는군."},{"who":"죠고","ja":"この差を分かっていながらも、引けないんだ!","kana":"この さを わかって いながらも、ひけない んだ!","ko":"이 차이를 알면서도 물러설 수 없어!"}],"words":[{"w":"炎","r":"ほのお","ko":"불꽃, 화염"},{"w":"必死","r":"ひっし","ko":"필사적임"},{"w":"差","r":"さ","ko":"차이"},{"w":"圧倒的","r":"あっとうてき","ko":"압도적"},{"w":"敗北","r":"はいぼく","ko":"패배"},{"w":"精一杯","r":"せいいっぱい","ko":"힘껏, 최선을 다해"},{"w":"打ち砕く","r":"うちくだく","ko":"산산이 부수다"},{"w":"未熟","r":"みじゅく","ko":"미숙함"}],"grammar":{"point":"〜ながらも","desc":"〜ながらも는 '~하면서도, ~이지만'이라는 역접 표현입니다. 동사 ます형 어간, い형용사, な형용사 어간, 명사에 바로 붙습니다(狭いながらも・未熟ながらも・子どもながらも). 그냥 ながら는 '~하면서(동시 동작)'이지만, も가 붙으면 '그런데도'라는 반전의 느낌이 생깁니다. 한국어 '좁지만 아늑한 집'처럼 앞의 약점을 인정하고 뒤에서 긍정할 때 자주 씁니다.","ex":[{"ja":"小さいながらも、自分の事務所を持っています。","kana":"ちいさい ながらも、じぶんの じむしょを もって います。","ko":"작지만 제 사무실을 갖고 있습니다."},{"ja":"忙しいと言いながらも、彼はいつも相談に乗ってくれます。","kana":"いそがしいと いいながらも、かれは いつも そうだんに のって くれます。","ko":"바쁘다고 하면서도 그는 늘 상담에 응해 줍니다."}]},"convert":{"anime":"なかなかやるじゃねえか。","real":"さすがですね。","note":"〜じゃねえか는 거친 남성 말투이고, 칭찬이라도 위에서 내려다보는 느낌입니다. 상대의 실력을 칭찬할 때는 さすがですね・お見事です가 무난합니다."},"mission":"고객에게 우리 사무실(또는 팀)을 '작지만 고객 한 분 한 분을 소중히 한다'고 소개해 보세요.","missionEx":{"ja":"小さいながらも、お客様一人ひとりを大切にしています。","kana":"ちいさい ながらも、おきゃくさま ひとり ひとりを たいせつに して います。","ko":"작지만 고객 한 분 한 분을 소중히 하고 있습니다."},"quiz":[{"q":"「좁지만 편한 집」에 맞는 표현은?","choices":["狭いながらも快適な家","狭いながら快適な家です","狭くてながらも快適な家"],"a":0,"why":"い형용사는 그대로 ながらも에 붙습니다(狭いながらも)."},{"q":"「敗北」의 뜻은?","choices":["불꽃","패배","미숙함"],"a":1,"why":"敗北(はいぼく)는 '패배'라는 뜻입니다."},{"q":"ながら와 ながらも의 차이로 맞는 것은?","choices":["둘 다 이유를 나타낸다","ながらも는 과거만 나타낸다","ながらも는 '~하면서도'라는 역접이다"],"a":2,"why":"も가 붙으면 '그런데도'라는 반전(역접)의 뜻이 됩니다."}]},"222":{"day":222,"ep":"39","epTitle":"揺蕩-弐-","epTitleKo":"요탕 2","title":"~하는 한편 — 〜一方で","watch":"39화 후반 · 스쿠나가 싸움을 즐기며 죠고를 몰아붙이는 장면","scene":"죠고는 모든 것을 걸고 진지하게 덤비지만, 스쿠나는 웃으며 상대를 시험하듯 싸운다. 아직 완전한 힘을 되찾지는 않았는데도 스쿠나의 여유는 무너지지 않는다. 죠고는 그 태도에 더욱 초조해진다.","lines":[{"who":"죠고","ja":"宿儺は笑っている一方で、少しも本気を出していない。","kana":"すくなは わらって いる いっぽうで、すこしも ほんきを だして いない。","ko":"스쿠나는 웃고 있는 한편, 조금도 진심을 내지 않는다."},{"who":"스쿠나","ja":"力は戻りつつある一方で、まだ本調子ではない。","kana":"ちからは もどりつつ ある いっぽうで、まだ ほんちょうし では ない。","ko":"힘은 돌아오고 있는 한편, 아직 제 컨디션은 아니다."},{"who":"죠고","ja":"私は真剣な一方で、あいつは遊んでいるだけだ。","kana":"わたしは しんけんな いっぽうで、あいつは あそんで いる だけだ。","ko":"나는 진지한데, 저 녀석은 놀고 있을 뿐이다."}],"words":[{"w":"復活","r":"ふっかつ","ko":"부활"},{"w":"冷酷","r":"れいこく","ko":"냉혹함"},{"w":"追い詰める","r":"おいつめる","ko":"궁지로 몰다"},{"w":"平然と","r":"へいぜんと","ko":"태연하게"},{"w":"支配","r":"しはい","ko":"지배"},{"w":"真剣","r":"しんけん","ko":"진지함"},{"w":"本能","r":"ほんのう","ko":"본능"},{"w":"収入","r":"しゅうにゅう","ko":"수입"}],"grammar":{"point":"〜一方で","desc":"〜一方で는 '~하는 한편(으로)'라는 뜻으로, 두 가지 사실을 나란히 대비하거나 동시에 일어나는 일을 말할 때 씁니다. 동사·い형용사는 보통형, な형용사는 〜な, 명사는 〜である에 붙습니다(真剣な一方で・学生である一方で). 한국어 '한편'과 거의 같아서 보고서나 상담 설명에서 아주 자주 쓰입니다. 비슷한 〜反面은 다음 날 배우는데, 一方で가 더 폭넓게 쓰입니다.","ex":[{"ja":"売上が伸びる一方で、経費も増えています。","kana":"うりあげが のびる いっぽうで、けいひも ふえて います。","ko":"매출이 느는 한편, 경비도 늘고 있습니다."},{"ja":"この保険は保障が手厚い一方で、保険料は少し高めです。","kana":"この ほけんは ほしょうが てあつい いっぽうで、ほけんりょうは すこし たかめ です。","ko":"이 보험은 보장이 두터운 한편, 보험료는 조금 높은 편입니다."}]},"convert":{"anime":"あいつは遊んでいるだけだ。","real":"あちらの方は、まだ余裕があるようです。","note":"あいつ는 제3자를 낮춰 부르는 말이라 업무에서는 쓰지 않습니다. あの方・あちらの方로 바꾸고, 단정 대신 〜ようです로 부드럽게 말합니다."},"mission":"가계부를 본 고객에게 '수입이 늘어난 한편, 지출도 늘었다'고 짚어 주세요.","missionEx":{"ja":"収入が増えた一方で、支出も増えていますね。","kana":"しゅうにゅうが ふえた いっぽうで、ししゅつも ふえて いますね。","ko":"수입이 늘어난 한편, 지출도 늘고 있네요."},"quiz":[{"q":"な형용사 「真剣」에 一方で를 붙인 올바른 형태는?","choices":["真剣だ一方で","真剣の一方で","真剣な一方で"],"a":2,"why":"な형용사는 〜な一方で 형태로 씁니다."},{"q":"「収入」의 읽는 법은?","choices":["しゅうにゅう","しゅにゅう","しゅうにゅ"],"a":0,"why":"収入은 しゅうにゅう, '수입'입니다."},{"q":"「매출이 느는 한편, 경비도 늘고 있다」에 맞는 것은?","choices":["売上が伸びるから、経費も増えている","売上が伸びる一方で、経費も増えている","売上が伸びつつも、経費が増えない"],"a":1,"why":"두 사실을 나란히 대비할 때 〜一方で를 씁니다."}]},"223":{"day":223,"ep":"39","epTitle":"揺蕩-弐-","epTitleKo":"요탕 2","title":"~인 반면 — 〜反面","watch":"39화 끝부분 · 스쿠나가 죠고의 술식을 평가하며 약점을 짚는 장면","scene":"죠고의 화염 술식은 화려하고 위력도 엄청나지만, 성격이 급한 탓에 공격이 단순해 스쿠나에게 계속 읽힌다. 스쿠나는 그 약점을 짚으면서도 꺾이지 않는 죠고의 기세는 마음에 들어 한다.","lines":[{"who":"스쿠나","ja":"お前の術は派手な反面、動きが単純すぎる。","kana":"おまえの じゅつは はでな はんめん、うごきが たんじゅん すぎる。","ko":"네 술식은 화려한 반면, 움직임이 너무 단순하다."},{"who":"죠고","ja":"短気な反面、この熱さこそが私の強さなのだ!","kana":"たんきな はんめん、この あつさ こそが わたしの つよさ なのだ!","ko":"성미가 급한 반면, 이 뜨거움이야말로 나의 강함이다!"},{"who":"스쿠나","ja":"その真っすぐな心だけは、嫌いではないぞ。","kana":"その まっすぐな こころ だけは、きらい では ないぞ。","ko":"그 올곧은 마음만큼은 싫지 않다."}],"words":[{"w":"器用","r":"きよう","ko":"손재주가 좋음, 요령이 좋음"},{"w":"欠点","r":"けってん","ko":"결점"},{"w":"長所","r":"ちょうしょ","ko":"장점"},{"w":"短所","r":"たんしょ","ko":"단점"},{"w":"性格","r":"せいかく","ko":"성격"},{"w":"派手","r":"はで","ko":"화려함"},{"w":"単純","r":"たんじゅん","ko":"단순함"},{"w":"魅力","r":"みりょく","ko":"매력"}],"grammar":{"point":"〜反面","desc":"〜反面은 '~인 반면'이라는 뜻으로, 하나의 대상이 가진 상반된 두 성질(장점과 단점)을 대비할 때 씁니다. 접속은 一方で와 같아서 보통형, な형용사는 〜な, 명사는 〜である에 붙습니다(便利な反面). 一方で는 서로 다른 두 일을 나란히 놓을 때도 쓰지만, 反面은 '같은 것의 양면'에 초점이 있습니다. 상품의 장단점을 설명할 때 그대로 쓸 수 있는 실전 표현입니다.","ex":[{"ja":"この商品は便利な反面、値段が高いです。","kana":"この しょうひんは べんりな はんめん、ねだんが たかい です。","ko":"이 상품은 편리한 반면, 가격이 비쌉니다."},{"ja":"一人暮らしは自由な反面、寂しいこともあります。","kana":"ひとりぐらしは じゆうな はんめん、さびしい ことも あります。","ko":"혼자 사는 것은 자유로운 반면, 외로울 때도 있습니다."}]},"convert":{"anime":"動きが単純すぎる。","real":"もう少し工夫が必要かもしれませんね。","note":"〜すぎる로 단정하는 비판은 상대를 깎아내리는 말이 됩니다. 업무에서는 '조금 더 궁리가 필요할지도 모르겠네요'처럼 완곡하게 말합니다."},"mission":"고객에게 어떤 금융상품이 '수익률이 높은 반면 위험도 있다'고 균형 있게 설명해 보세요.","missionEx":{"ja":"この商品は利回りが高い反面、リスクもあります。","kana":"この しょうひんは りまわりが たかい はんめん、りすくも あります。","ko":"이 상품은 수익률이 높은 반면, 리스크도 있습니다."},"quiz":[{"q":"〜反面이 가장 잘 어울리는 문장은?","choices":["駅に行く反面、友達に会った","便利な反面、値段が高い","雨が降る反面、傘を買う"],"a":1,"why":"反面은 같은 대상의 상반된 두 성질(편리함↔비쌈)을 대비합니다."},{"q":"「短所」의 뜻은?","choices":["장점","단점","성격"],"a":1,"why":"短所(たんしょ)는 단점, 長所(ちょうしょ)는 장점입니다."},{"q":"「派手」의 읽는 법은?","choices":["はで","はて","ぱで"],"a":0,"why":"派手는 はで, '화려함'이라는 뜻입니다."}]},"225":{"day":225,"ep":"40","epTitle":"霹靂","epTitleKo":"벽력","title":"~하는 대로 / ~에 달렸다 — 〜次第","watch":"40화 전반 · 죠고의 거대 운석과 스쿠나의 불꽃 화살이 맞부딪히는 장면","scene":"궁지에 몰린 죠고는 남은 힘을 모아 거대한 운석을 떨어뜨린다. 스쿠나는 그에 맞서 불의 술식을 처음으로 꺼내 들고, 화염의 대결 끝에 승부가 갈린다.","lines":[{"who":"죠고","ja":"準備ができ次第、私の最大の一撃を落とす!","kana":"じゅんびが でき しだい、わたしの さいだいの いちげきを おとす!","ko":"준비가 되는 대로 최대의 일격을 떨어뜨리겠다!"},{"who":"스쿠나","ja":"勝つか負けるかは、すべてお前の力次第だ。","kana":"かつか まけるかは、すべて おまえの ちから しだいだ。","ko":"이기느냐 지느냐는 네 힘에 달렸다."},{"who":"스쿠나","ja":"…これで決着がついたな。なかなか楽しめたぞ。","kana":"…これで けっちゃくが ついたな。なかなか たのしめたぞ。","ko":"…이걸로 결판이 났군. 꽤 즐거웠다."}],"words":[{"w":"勝利","r":"しょうり","ko":"승리"},{"w":"衝撃","r":"しょうげき","ko":"충격"},{"w":"吹き飛ばす","r":"ふきとばす","ko":"날려 버리다"},{"w":"一気に","r":"いっきに","ko":"단숨에"},{"w":"直ちに","r":"ただちに","ko":"즉시, 곧바로"},{"w":"改めて","r":"あらためて","ko":"다시, 새삼"},{"w":"問い合わせる","r":"といあわせる","ko":"문의하다"},{"w":"間もなく","r":"まもなく","ko":"곧, 머지않아"}],"grammar":{"point":"〜次第","desc":"〜次第는 두 가지로 씁니다. ① 동사 ます형 어간 + 次第: '~하는 대로 곧바로'(届き次第・決まり次第). ② 명사 + 次第(だ/で): '~에 달려 있다'(結果次第・あなた次第). ①은 '자료가 도착하는 대로 연락드리겠습니다'처럼 업무 메일·전화의 단골 표현이고, 미래의 일에만 씁니다. ②는 한국어 '~하기 나름'과 같은 느낌입니다.","ex":[{"ja":"資料が届き次第、すぐにご連絡いたします。","kana":"しりょうが とどき しだい、すぐに ごれんらく いたします。","ko":"자료가 도착하는 대로 바로 연락드리겠습니다."},{"ja":"保険料は年齢と健康状態次第で変わります。","kana":"ほけんりょうは ねんれいと けんこう じょうたい しだいで かわります。","ko":"보험료는 나이와 건강 상태에 따라 달라집니다."}]},"convert":{"anime":"お前の力次第だ。","real":"お客様のご判断次第です。","note":"お前는 상대를 낮추는 호칭이고 だ는 반말입니다. 고객에게는 お客様のご〜次第です처럼 존경 표현과 です로 말합니다."},"mission":"고객에게 '서류를 확인하는 대로 전화드리겠다'고 약속해 보세요.","missionEx":{"ja":"書類を確認し次第、お電話いたします。","kana":"しょるいを かくにん し しだい、おでんわ いたします。","ko":"서류를 확인하는 대로 전화드리겠습니다."},"quiz":[{"q":"「도착하는 대로 연락드리겠습니다」에 맞는 것은?","choices":["着いた次第、連絡します","着く次第、連絡します","着き次第、連絡します"],"a":2,"why":"'~하는 대로'의 次第는 ます형 어간(着き)에 붙습니다."},{"q":"「結果次第」의 뜻은?","choices":["결과에 달려 있다","결과가 나온 뒤에","결과와 상관없이"],"a":0,"why":"명사 + 次第는 '~에 달려 있다'는 뜻입니다."},{"q":"「間もなく」의 뜻은?","choices":["승리","곧, 머지않아","문의하다"],"a":1,"why":"間もなく(まもなく)는 '곧, 머지않아'라는 뜻입니다."}]},"226":{"day":226,"ep":"40","epTitle":"霹靂","epTitleKo":"벽력","title":"~한 다음에 / ~하는 데 있어 — 〜上で","watch":"40화 · 쓰러진 죠고에게 스쿠나가 실력을 인정하는 말을 건네는 장면","scene":"싸움에서 진 죠고에게 스쿠나는 뜻밖에도 그의 강함을 인정하는 말을 남긴다. 직접 힘을 겨뤄 본 뒤에야 죠고는 둘 사이의 차이를 깨닫고, 그 인정 속에서 묘한 위로를 받는다.","lines":[{"who":"스쿠나","ja":"力を比べた上で言おう。お前は強かった。","kana":"ちからを くらべた うえで いおう。おまえは つよかった。","ko":"힘을 겨뤄 본 다음에 말하마. 너는 강했다."},{"who":"죠고","ja":"戦った上で、ようやく差が分かった…。","kana":"たたかった うえで、ようやく さが わかった…。","ko":"싸워 본 다음에야 겨우 차이를 알았다…."},{"who":"스쿠나","ja":"胸を張れ。この俺がそう言うのだからな。","kana":"むねを はれ。この おれが そう いうの だからな。","ko":"가슴을 펴라. 이 내가 그렇게 말하는 거니까."}],"words":[{"w":"見抜く","r":"みぬく","ko":"간파하다, 꿰뚫어 보다"},{"w":"誠実","r":"せいじつ","ko":"성실함"},{"w":"価値観","r":"かちかん","ko":"가치관"},{"w":"素質","r":"そしつ","ko":"소질"},{"w":"自覚","r":"じかく","ko":"자각"},{"w":"見直す","r":"みなおす","ko":"다시 보다, 재평가하다"},{"w":"立派","r":"りっぱ","ko":"훌륭함"},{"w":"誇り","r":"ほこり","ko":"자부심, 긍지"}],"grammar":{"point":"〜上で","desc":"〜上で는 두 가지로 씁니다. ① 동사 た형 + 上で: '~한 다음에(그것을 바탕으로)'(相談した上で決めます). 단순한 순서가 아니라 '앞의 일을 확실히 끝내고 그 결과를 토대로'라는 느낌입니다. ② 동사 사전형/명사の + 上で: '~하는 데 있어서'(契約の上で大切なこと). 계약·상담 설명에서 '충분히 이해하신 다음에'라는 말로 매우 자주 씁니다.","ex":[{"ja":"内容をご理解いただいた上で、ご契約ください。","kana":"ないようを ごりかい いただいた うえで、ごけいやく ください。","ko":"내용을 이해하신 다음에 계약해 주십시오."},{"ja":"家族と相談した上で、お返事します。","kana":"かぞくと そうだん した うえで、おへんじ します。","ko":"가족과 상의한 다음에 답을 드리겠습니다."}]},"convert":{"anime":"胸を張れ。","real":"自信を持ってください。","note":"張れ는 명령형이라 윗사람이 아랫사람에게 하는 말투입니다. 상대를 격려할 때는 自信を持ってください처럼 〜てください로 바꿉니다."},"mission":"고객에게 '설명을 다 들으신 다음에 천천히 고르시라'고 권해 보세요.","missionEx":{"ja":"ご説明を聞いた上で、ゆっくり選んでください。","kana":"ごせつめいを きいた うえで、ゆっくり えらんで ください。","ko":"설명을 들으신 다음에 천천히 골라 주세요."},"quiz":[{"q":"「상의한 다음에 정하겠습니다」에 맞는 것은?","choices":["相談した上で決めます","相談する上で決めました","相談の上に決めます"],"a":0,"why":"'~한 다음에'는 た형 + 上で입니다."},{"q":"「誠実」의 읽는 법은?","choices":["せいしつ","しょうじつ","せいじつ"],"a":2,"why":"誠実는 せいじつ, '성실함'이라는 뜻입니다."},{"q":"「見直す」의 뜻은?","choices":["간파하다","다시 보다, 재평가하다","자부심"],"a":1,"why":"見直す(みなおす)는 '다시 보다, 재평가하다'라는 뜻입니다."}]},"227":{"day":227,"ep":"40","epTitle":"霹靂","epTitleKo":"벽력","title":"~할 때(격식) — 〜際に","watch":"40화 · 고요한 바닷가 같은 공간에서 죠고가 먼저 간 동료들과 재회하는 장면","scene":"싸움이 끝난 뒤 죠고는 조용한 바닷가 같은 곳에서 먼저 떠난 동료 하나미 등과 다시 만난다. 분함보다 후련함이 남았음을 깨달은 죠고는, 동료들과 함께한 시간을 돌아보며 담담히 마음을 정리한다.","lines":[{"who":"하나미","ja":"お帰りなさい。ここでずっと待っていましたよ。","kana":"おかえりなさい。ここで ずっと まって いましたよ。","ko":"어서 와요. 여기서 계속 기다리고 있었어요."},{"who":"죠고","ja":"負けた際に、悔しさより満足が残った。","kana":"まけた さいに、くやしさ より まんぞくが のこった。","ko":"졌을 때, 분함보다 만족이 남았다."},{"who":"하나미","ja":"次に生まれる際には、また一緒にいましょう。","kana":"つぎに うまれる さいには、また いっしょに いましょう。","ko":"다음에 태어날 때에는 또 함께 있어요."}],"words":[{"w":"再会","r":"さいかい","ko":"재회"},{"w":"満足","r":"まんぞく","ko":"만족"},{"w":"寄り添う","r":"よりそう","ko":"곁에 다가붙다, 함께하다"},{"w":"潮風","r":"しおかぜ","ko":"바닷바람"},{"w":"晴れやか","r":"はれやか","ko":"후련하다, 개운하다"},{"w":"打ち明ける","r":"うちあける","ko":"털어놓다"},{"w":"本心","r":"ほんしん","ko":"본심"},{"w":"思い残す","r":"おもいのこす","ko":"미련을 남기다"}],"grammar":{"point":"〜際に","desc":"〜際に는 '~할 때, ~하는 경우에'라는 뜻으로, 〜時に의 격식 있는 버전입니다. 동사 사전형/た형 + 際に, 명사 + の際に로 씁니다(ご来店の際に・提出する際に). 안내문, 매장 공지, 계약 설명 등 공식적인 자리에서 거의 정해진 표현처럼 쓰입니다. 일상 대화에서 친구에게 쓰면 딱딱하게 들리니 업무용으로 기억해 두세요.","ex":[{"ja":"ご来店の際には、身分証をお持ちください。","kana":"ごらいてんの さいには、みぶんしょうを おもち ください。","ko":"내점하실 때에는 신분증을 지참해 주십시오."},{"ja":"書類を提出する際に、印鑑が必要です。","kana":"しょるいを ていしゅつ する さいに、いんかんが ひつよう です。","ko":"서류를 제출할 때 도장이 필요합니다."}]},"convert":{"anime":"来る時、これ持ってきて。","real":"ご来社の際に、こちらをお持ちいただけますか。","note":"時→際に로 바꾸면 격식이 올라가고, 持ってきて(반말 부탁)는 お持ちいただけますか로 정중하게 바꿉니다."},"mission":"상담 예약 고객에게 '방문하실 때 보험증권을 가져와 달라'고 안내해 보세요.","missionEx":{"ja":"ご来社の際には、保険証券をお持ちください。","kana":"ごらいしゃの さいには、ほけん しょうけんを おもち ください。","ko":"내방하실 때에는 보험증권을 지참해 주십시오."},"quiz":[{"q":"명사 「来店」에 際に를 붙인 올바른 형태는?","choices":["来店際に","来店の際に","来店な際に"],"a":1,"why":"명사는 〜の際に 형태로 씁니다."},{"q":"〜際に와 가장 뜻이 가까운 것은?","choices":["〜時に","〜から","〜のに"],"a":0,"why":"〜際に는 〜時に의 격식 있는 표현입니다."},{"q":"「打ち明ける」의 뜻은?","choices":["재회","배웅하다","털어놓다"],"a":2,"why":"打ち明ける(うちあける)는 '털어놓다'라는 뜻입니다."}]},"228":{"day":228,"ep":"40","epTitle":"霹靂","epTitleKo":"벽력","title":"~에 따라 — 〜に応じて","watch":"40화 후반 · 싸움을 끝낸 스쿠나가 다음 상대를 찾아 시부야를 걷는 장면","scene":"죠고와의 싸움을 끝낸 스쿠나는 아직 이타도리에게 몸을 돌려주지 않은 채 시부야 거리를 걷는다. 상대에 따라 놀이 방식을 바꿀 뿐이라는 듯 여유를 부리며 다음 상대를 찾고, 시부야 곳곳에서는 술사들이 상황에 맞춰 각자의 싸움을 이어간다.","lines":[{"who":"스쿠나","ja":"相手の強さに応じて、遊び方を変えるだけだ。","kana":"あいての つよさに おうじて、あそびかたを かえる だけだ。","ko":"상대의 강함에 따라 노는 방식을 바꿀 뿐이다."},{"who":"스쿠나","ja":"次は誰だ。状況に応じて楽しませてもらう。","kana":"つぎは だれだ。じょうきょうに おうじて たのしませて もらう。","ko":"다음은 누구냐. 상황에 따라 즐기도록 하지."},{"who":"스쿠나","ja":"小僧が目を覚ますまで、好きにさせてもらうぞ。","kana":"こぞうが めを さます まで、すきに させて もらうぞ。","ko":"꼬맹이가 깨어날 때까지 마음대로 하겠다."}],"words":[{"w":"気まぐれ","r":"きまぐれ","ko":"변덕"},{"w":"希望","r":"きぼう","ko":"희망"},{"w":"見下ろす","r":"みおろす","ko":"내려다보다"},{"w":"切り替える","r":"きりかえる","ko":"전환하다, 바꾸다"},{"w":"料金","r":"りょうきん","ko":"요금"},{"w":"好奇心","r":"こうきしん","ko":"호기심"},{"w":"予算","r":"よさん","ko":"예산"},{"w":"提案","r":"ていあん","ko":"제안"}],"grammar":{"point":"〜に応じて","desc":"명사 + に応じて는 '~에 따라, ~에 맞춰'라는 뜻입니다. 앞의 조건(나이, 예산, 희망, 상황)이 달라지면 뒤의 내용도 그에 맞게 달라진다는 의미입니다. 〜によって와 비슷하지만, に応じて는 '상대의 요구나 조건에 맞춰 대응한다'는 느낌이 강해서 서비스·상담 안내에 딱 맞습니다. 명사를 수식할 때는 〜に応じた(ご予算に応じたプラン)로 씁니다.","ex":[{"ja":"ご予算に応じて、プランをご提案いたします。","kana":"ごよさんに おうじて、ぷらんを ごていあん いたします。","ko":"예산에 맞춰 플랜을 제안해 드리겠습니다."},{"ja":"年齢に応じて、保険料が変わります。","kana":"ねんれいに おうじて、ほけんりょうが かわります。","ko":"나이에 따라 보험료가 달라집니다."}]},"convert":{"anime":"好きにさせてもらうぞ。","real":"では、こちらで進めさせていただきます。","note":"好きにさせてもらうぞ는 상대 의사를 무시하는 거친 선언입니다. 업무에서는 〜させていただきます로 '허락을 받아 진행한다'는 겸손한 형태로 바꿉니다."},"mission":"고객에게 '희망하시는 내용에 맞춰 보장 내용을 조정할 수 있다'고 설명해 보세요.","missionEx":{"ja":"お客様のご希望に応じて、内容を調整できます。","kana":"おきゃくさまの ごきぼうに おうじて、ないようを ちょうせい できます。","ko":"고객님의 희망에 따라 내용을 조정할 수 있습니다."},"quiz":[{"q":"「예산에 맞춘 플랜」에 맞는 표현은?","choices":["予算に応じてプラン","予算に応じたプラン","予算の応じるプラン"],"a":1,"why":"명사를 수식할 때는 〜に応じた + 명사를 씁니다."},{"q":"「見下ろす」의 읽는 법은?","choices":["みくだす","みしたろす","みおろす"],"a":2,"why":"見下ろす는 みおろす, '내려다보다'라는 뜻입니다."},{"q":"「年齢に応じて」의 뜻은?","choices":["나이에 따라","나이와 상관없이","나이 때문에"],"a":0,"why":"〜に応じて는 '~에 따라, ~에 맞춰'입니다."}]},"229":{"day":229,"ep":"41","epTitle":"霹靂-弐-","epTitleKo":"벽력 2","title":"〜わりに — ~에 비해, ~치고는","watch":"41화 전반부 · 스쿠나 vs 마허라 전투","scene":"메구미가 목숨을 걸고 불러낸 최강의 식신 마허라는 한 번 받은 공격에 적응하며 스쿠나를 몰아붙인다. 스쿠나는 오히려 이 상대를 즐기며 시부야 한복판에서 싸움을 이어 간다.","lines":[{"who":"스쿠나","ja":"図体が大きいわりに、ずいぶん動きが速いな。","kana":"ずうたいが おおきい わりに、ずいぶん うごきが はやいな。","ko":"덩치가 큰 것에 비해 꽤 움직임이 빠르군."},{"who":"내레이션","ja":"年齢のわりに、伏黒の覚悟はあまりに重かった。","kana":"ねんれいの わりに、ふしぐろの かくごは あまりに おもかった。","ko":"나이에 비해 후시구로의 각오는 너무나 무거웠다."},{"who":"스쿠나","ja":"時間をかけたわりに、結果は変わらんぞ。","kana":"じかんを かけた わりに、けっかは かわらんぞ。","ko":"시간을 들인 것치고 결과는 안 바뀐다."}],"words":[{"w":"跳ね返す","r":"はねかえす","ko":"튕겨 내다"},{"w":"案外","r":"あんがい","ko":"의외로"},{"w":"図太い","r":"ずぶとい","ko":"배짱이 두둑하다, 뻔뻔하다"},{"w":"鋭い","r":"するどい","ko":"날카롭다"},{"w":"鈍い","r":"にぶい","ko":"둔하다"},{"w":"見極める","r":"みきわめる","ko":"끝까지 보고 판단하다"},{"w":"意外","r":"いがい","ko":"의외"},{"w":"適応","r":"てきおう","ko":"적응"}],"grammar":{"point":"〜わりに","desc":"〜わりに는 '~에 비해서, ~치고는'이라는 뜻으로, 어떤 기준(나이·가격·노력 등)에서 보통 예상되는 것과 실제가 다를 때 씁니다. 명사는 の를 넣어 年齢のわりに, い형용사는 그대로 高いわりに, な형용사는 な를 넣어 静かなわりに, 동사는 보통형에 붙여 勉強したわりに가 됩니다. 좋은 쪽(값에 비해 좋다)과 나쁜 쪽(노력에 비해 결과가 없다) 모두에 쓸 수 있어 상품 설명에도 자주 나옵니다.","ex":[{"ja":"この保険は保障が手厚いわりに、保険料が安いです。","kana":"この ほけんは ほしょうが てあつい わりに、ほけんりょうが やすいです。","ko":"이 보험은 보장이 든든한 것에 비해 보험료가 쌉니다."},{"ja":"値段のわりに、このホテルは部屋が広いですね。","kana":"ねだんの わりに、この ほてるは へやが ひろいですね。","ko":"가격에 비해 이 호텔은 방이 넓네요."}]},"convert":{"anime":"デカいわりに速えじゃねえか。","real":"大きいわりに、動きが速いですね。","note":"デカい·速え·じゃねえか는 거친 남성 반말 축약입니다. 업무 자리에서는 大きい·速い를 제대로 발음하고 〜ですね로 부드럽게 감탄합니다."},"mission":"고객에게 상품이나 서비스의 장점을 〜わりに로 설명해 보세요. (예: 나이에 비해 보험료가 적당하다, 가격에 비해 보장이 넓다)","missionEx":{"ja":"年齢のわりに、保険料はお手頃ですよ。","kana":"ねんれいの わりに、ほけんりょうは おてごろですよ。","ko":"연령에 비해 보험료는 적당한 편이에요."},"quiz":[{"q":"「나이에 비해 젊어 보입니다」를 일본어로?","choices":["年齢のわりに若く見えます。","年齢わりに若く見えます。","年齢なわりに若く見えます。"],"a":0,"why":"명사에는 の를 넣어 〜のわりに로 씁니다."},{"q":"「静か」에 わりに를 붙인 올바른 형태는?","choices":["静かのわりに","静かだわりに","静かなわりに"],"a":2,"why":"な형용사는 な를 넣어 〜なわりに가 됩니다."},{"q":"「見極める」의 읽는 법은?","choices":["みごくめる","みきわめる","みきょくめる"],"a":1,"why":"見極める는 みきわめる, '끝까지 보고 판단하다'라는 뜻입니다."}]},"230":{"day":230,"ep":"41","epTitle":"霹靂-弐-","epTitleKo":"벽력 2","title":"〜にしては — ~치고는 (예상 밖)","watch":"41화 중반 · 스쿠나의 영역과 불꽃 화살","scene":"스쿠나는 적응을 거듭하는 마허라를 상대로 압도적인 영역과 불꽃 기술까지 꺼내 결국 싸움을 끝낸다. 그 여파로 시부야 일대가 큰 피해를 입지만, 스쿠나는 쓰러진 메구미만은 살려 둔다.","lines":[{"who":"스쿠나","ja":"式神にしては、なかなか楽しませてくれたな。","kana":"しきがみに しては、なかなか たのしませて くれたな。","ko":"식신치고는 꽤 즐겁게 해 줬군."},{"who":"스쿠나","ja":"小僧の体にしては、悪くない動きができた。","kana":"こぞうの からだに しては、わるくない うごきが できた。","ko":"꼬맹이 몸치고는 나쁘지 않게 움직였다."},{"who":"스쿠나","ja":"締めくくりだ。この炎の矢を受けてみろ。","kana":"しめくくりだ。この ほのおの やを うけて みろ。","ko":"마무리다. 이 불꽃 화살을 받아 봐라."}],"words":[{"w":"突き刺す","r":"つきさす","ko":"꿰뚫다, 찌르다"},{"w":"矢","r":"や","ko":"화살"},{"w":"優秀","r":"ゆうしゅう","ko":"우수함"},{"w":"慎重","r":"しんちょう","ko":"신중함"},{"w":"珍しい","r":"めずらしい","ko":"드물다, 신기하다"},{"w":"大胆","r":"だいたん","ko":"대담함"},{"w":"完璧","r":"かんぺき","ko":"완벽"},{"w":"正確","r":"せいかく","ko":"정확함"}],"grammar":{"point":"〜にしては","desc":"〜にしては는 '~치고는'이라는 뜻으로, 어떤 특정한 조건(신입·초보·처음 등)이라면 보통 이럴 텐데 실제는 다르다는 놀람을 나타냅니다. 명사나 동사 보통형에 바로 붙입니다(新人にしては, 初めてにしては, 準備したにしては). 어제 배운 わりに와 비슷하지만, にしては는 '그 사람·그 상황이 ~라는 사실'에 대한 놀람이 더 강하고, い형용사·な형용사에는 잘 붙이지 않습니다. 칭찬할 때 '新人にしては上手ですね'처럼 아주 자주 씁니다.","ex":[{"ja":"新人にしては、説明がとても上手ですね。","kana":"しんじんに しては、せつめいが とても じょうずですね。","ko":"신입치고는 설명을 아주 잘하네요."},{"ja":"初めての日本旅行にしては、完璧な計画ですね。","kana":"はじめての にほん りょこうに しては、かんぺきな けいかくですね。","ko":"첫 일본 여행치고는 완벽한 계획이네요."}]},"convert":{"anime":"新人にしちゃ、やるじゃん。","real":"新人にしては、よくできていますね。","note":"〜にしちゃ는 〜にしては의 회화 축약이고 やるじゃん은 친구끼리 쓰는 반말 칭찬입니다. 회사에서는 축약을 풀고 よくできていますね로 정중하게 칭찬합니다."},"mission":"후배나 신입 직원을 〜にしては로 칭찬해 보세요. (예: 신입치고 상담을 잘한다, 처음치고 준비가 완벽하다)","missionEx":{"ja":"初めての相談にしては、準備が完璧でしたよ。","kana":"はじめての そうだんに しては、じゅんびが かんぺきでしたよ。","ko":"첫 상담치고는 준비가 완벽했어요."},"quiz":[{"q":"「신입치고는 잘하네요」를 일본어로?","choices":["新人のにしては上手ですね。","新人にしては上手ですね。","新人なにしては上手ですね。"],"a":1,"why":"명사에는 にしては를 바로 붙입니다."},{"q":"〜にしちゃ의 원래 형태는?","choices":["〜にしては","〜にしても","〜にしたら"],"a":0,"why":"〜にしちゃ는 〜にしては를 줄인 회화체입니다."},{"q":"「珍しい」의 뜻은?","choices":["완벽하다","능숙하다","드물다"],"a":2,"why":"珍しい(めずらしい)는 '드물다, 신기하다'입니다."}]},"232":{"day":232,"ep":"41","epTitle":"霹靂-弐-","epTitleKo":"벽력 2","title":"〜くせに — ~주제에, ~면서","watch":"41화 후반부 · 몸을 되찾은 이타도리","scene":"스쿠나가 물러나고 몸을 되찾은 이타도리는 폐허가 된 시부야 거리를 마주한다. 자기 몸이 이 모든 일을 일으켰다는 사실을 깨닫고, 사람을 돕겠다고 했던 자신을 탓하며 무너진다.","lines":[{"who":"이타도리","ja":"人を助けるって言ったくせに、俺は何してんだ。","kana":"ひとを たすけるって いった くせに、おれは なに してんだ。","ko":"사람을 돕겠다고 해 놓고, 난 뭘 하고 있는 거야."},{"who":"스쿠나","ja":"弱いくせに、偉そうに文句を言うな、小僧。","kana":"よわい くせに、えらそうに もんくを いうな、こぞう。","ko":"약해 빠진 주제에 잘난 척 불평하지 마라, 꼬맹이."},{"who":"이타도리","ja":"守るって言葉は、嘘じゃなかったはずなのに…。","kana":"まもるって ことばは、うそじゃ なかった はずなのに…。","ko":"지키겠다는 말은 거짓말이 아니었을 텐데…."}],"words":[{"w":"立ち尽くす","r":"たちつくす","ko":"우두커니 서 있다"},{"w":"現実","r":"げんじつ","ko":"현실"},{"w":"無責任","r":"むせきにん","ko":"무책임"},{"w":"偉そう","r":"えらそう","ko":"잘난 척하는 듯함"},{"w":"言い返す","r":"いいかえす","ko":"말대꾸하다"},{"w":"卑怯","r":"ひきょう","ko":"비겁함"},{"w":"誤魔化す","r":"ごまかす","ko":"얼버무리다, 속이다"},{"w":"無口","r":"むくち","ko":"말수가 적음"}],"grammar":{"point":"〜くせに","desc":"〜くせに는 '~인 주제에, ~이면서'라는 뜻으로, のに와 같은 역접이지만 상대(또는 자신)를 탓하고 비난하는 감정이 강하게 들어갑니다. 접속은 のに와 같아서 동사·い형용사는 보통형(知っているくせに, 弱いくせに), 명사는 の(子どものくせに), な형용사는 な(下手なくせに)를 넣습니다. 비난의 뉘앙스가 강하므로 고객이나 윗사람에게는 쓰지 않고, 친한 사이의 농담이나 혼잣말·자책에서 주로 씁니다.","ex":[{"ja":"彼は知っているくせに、何も教えてくれません。","kana":"かれは しって いる くせに、なにも おしえて くれません。","ko":"그는 알면서도 아무것도 가르쳐 주지 않아요."},{"ja":"自分で決めたくせに、文句ばかり言わないでください。","kana":"じぶんで きめた くせに、もんく ばかり いわないで ください。","ko":"자기가 정해 놓고 불평만 하지 마세요."}]},"convert":{"anime":"知ってたくせに、黙ってたのかよ。","real":"ご存じだったのでしたら、教えていただきたかったです。","note":"〜くせに는 상대를 비난하는 말이라 업무에서 쓰면 관계가 틀어집니다. 고객이나 상사에게는 ご存じ(아시다)와 〜ていただきたかったです로 아쉬움만 정중하게 전합니다."},"mission":"자신이 '말만 하고 못 지킨 일'을 〜くせに로 가볍게 자책해 보세요. (예: 운동한다고 해 놓고, 일찍 잔다고 해 놓고)","missionEx":{"ja":"ダイエットすると言ったくせに、また夜食を食べました。","kana":"だいえっと すると いった くせに、また やしょくを たべました。","ko":"다이어트한다고 해 놓고 또 야식을 먹었어요."},"quiz":[{"q":"〜くせに와 〜のに의 차이로 맞는 것은?","choices":["くせに가 더 정중하다","의미가 완전히 같다","くせに에는 비난의 감정이 강하다"],"a":2,"why":"くせに는 상대를 탓하는 감정이 강해 윗사람에게는 쓰지 않습니다."},{"q":"「아이인 주제에」를 일본어로?","choices":["子どもなくせに","子どものくせに","子どもくせに"],"a":1,"why":"명사에는 の를 넣어 〜のくせに로 씁니다."},{"q":"「無口」의 뜻은?","choices":["말수가 적음","우두커니 서 있다","얼버무리다"],"a":0,"why":"無口(むくち)는 '말수가 적음'이라는 뜻입니다."}]},"233":{"day":233,"ep":"41","epTitle":"霹靂-弐-","epTitleKo":"벽력 2","title":"〜ほど〜ない — ~만큼 ~하지 않다","watch":"41화 마지막 · 폐허 속을 걷는 이타도리","scene":"이타도리는 연기와 불길이 남은 거리를 비틀거리며 걷는다. 몸의 아픔보다 마음의 고통이 훨씬 크지만, 그는 멈추지 않고 다음 싸움터를 향해 발걸음을 옮긴다.","lines":[{"who":"이타도리","ja":"これほどひどい景色は、見たことがない…。","kana":"これほど ひどい けしきは、みた ことが ない…。","ko":"이렇게 끔찍한 광경은 본 적이 없어…."},{"who":"이타도리","ja":"体の痛みなんて、この苦しさほどじゃない。","kana":"からだの いたみ なんて、この くるしさ ほど じゃない。","ko":"몸의 아픔 따위는 이 괴로움만큼은 아니야."},{"who":"내레이션","ja":"被害は、誰も想像できないほど大きかった。","kana":"ひがいは、だれも そうぞう できない ほど おおきかった。","ko":"피해는 누구도 상상할 수 없을 만큼 컸다."}],"words":[{"w":"被害","r":"ひがい","ko":"피해"},{"w":"犠牲","r":"ぎせい","ko":"희생"},{"w":"建物","r":"たてもの","ko":"건물"},{"w":"地面","r":"じめん","ko":"지면, 땅바닥"},{"w":"煙","r":"けむり","ko":"연기"},{"w":"心細い","r":"こころぼそい","ko":"막막하다, 불안하다"},{"w":"想像","r":"そうぞう","ko":"상상"},{"w":"泣き出す","r":"なきだす","ko":"울음을 터뜨리다"}],"grammar":{"point":"〜ほど〜ない","desc":"AはBほど〜ない는 'A는 B만큼 ~하지 않다'라는 비교 표현입니다. B 자리에 비교 기준을 두고, 뒤에는 반드시 부정형이 옵니다(去年ほど忙しくない, 思ったほど高くない). これほど·それほど 형태로 '이 정도로(는) ~하지 않다'처럼도 씁니다. 한국어 '~만큼은 아니다'와 거의 같아서 익히기 쉽고, 숫자 없이 부드럽게 비교할 때 업무에서도 자주 씁니다.","ex":[{"ja":"今年は去年ほど忙しくないです。","kana":"ことしは きょねん ほど いそがしく ないです。","ko":"올해는 작년만큼 바쁘지 않습니다."},{"ja":"この商品は、思ったほど高くありません。","kana":"この しょうひんは、おもった ほど たかく ありません。","ko":"이 상품은 생각했던 것만큼 비싸지 않습니다."}]},"convert":{"anime":"そんなに大したことねえよ。","real":"それほど大きな問題ではございません。","note":"大したことねえ는 '별거 아냐'라는 거친 반말입니다. 고객에게는 それほど〜ない 구문과 ございません을 써서 '그렇게 큰 문제는 아닙니다'라고 안심시킵니다."},"mission":"고객이 걱정하는 점(보험료, 절차 등)이 생각만큼 어렵지 않다고 〜ほど〜ない로 안심시켜 보세요.","missionEx":{"ja":"手続きは、思ったほど難しくありませんよ。","kana":"てつづきは、おもった ほど むずかしく ありませんよ。","ko":"절차는 생각하신 것만큼 어렵지 않아요."},"quiz":[{"q":"「올해는 작년만큼 덥지 않다」를 일본어로?","choices":["今年は去年ほど暑くない。","今年は去年ほど暑い。","今年は去年より暑くない。"],"a":0,"why":"AはBほど〜ない는 뒤에 부정형이 와야 합니다."},{"q":"「それほど〜ない」의 뜻으로 알맞은 것은?","choices":["그것보다 더 ~하다","그렇게까지 ~하지 않다","그것 때문에 ~하다"],"a":1,"why":"それほど〜ない는 '그 정도로 ~하지는 않다'입니다."},{"q":"「煙」의 읽는 법은?","choices":["ほのお","けしき","けむり"],"a":2,"why":"煙는 けむり(연기)입니다."}]},"234":{"day":234,"ep":"42","epTitle":"理非","epTitleKo":"이비","title":"〜に決まっている — 분명 ~하다, ~임에 틀림없다","watch":"42화 전반부 · 상처 입은 나나미의 행군","scene":"큰 부상을 입은 나나미는 몸을 끌다시피 걸으며 앞을 막는 적들을 쓰러뜨린다. 지친 그의 머릿속에는 회사원 시절의 기억과, 언젠가 남쪽 나라 바닷가에서 조용히 책을 읽으며 살고 싶다는 꿈이 스쳐 간다.","lines":[{"who":"나나미","ja":"この傷では、長く戦えないに決まっています。","kana":"この きずでは、ながく たたかえないに きまって います。","ko":"이 상처로는 오래 못 싸울 게 뻔합니다."},{"who":"나나미","ja":"南の海辺で本を読む毎日は、楽しいに決まってる。","kana":"みなみの うみべで ほんを よむ まいにちは、たのしいに きまってる。","ko":"남쪽 바닷가에서 책 읽는 나날은 분명 즐거울 거다."},{"who":"나나미","ja":"残業より、こっちのほうがよほど疲れますね。","kana":"ざんぎょう より、こっちの ほうが よほど つかれますね。","ko":"야근보다 이쪽이 훨씬 피곤하군요."}],"words":[{"w":"理想","r":"りそう","ko":"이상"},{"w":"何となく","r":"なんとなく","ko":"왠지, 그냥"},{"w":"退職","r":"たいしょく","ko":"퇴직"},{"w":"うんざり","r":"うんざり","ko":"지긋지긋함, 질림"},{"w":"南","r":"みなみ","ko":"남쪽"},{"w":"暮らす","r":"くらす","ko":"살다, 지내다"},{"w":"当然","r":"とうぜん","ko":"당연"},{"w":"ぐったり","r":"ぐったり","ko":"녹초가 됨, 축 늘어짐"}],"grammar":{"point":"〜に決まっている","desc":"〜に決まっている는 '분명 ~이다, ~임에 틀림없다, 당연히 ~이다'라는 강한 확신을 나타냅니다. 동사·い형용사 보통형, 명사·な형용사 어간에 바로 붙입니다(勝つに決まっている, 高いに決まっている, 嘘に決まっている). 회화에서는 〜に決まってる로 줄여 자주 말합니다. 단정이 강하므로 고객 앞에서는 '〜と思います'나 '〜はずです'로 부드럽게 바꾸는 것이 안전하고, 친한 사이나 혼잣말에서 쓰기 좋습니다.","ex":[{"ja":"毎日練習すれば、上手になるに決まっていますよ。","kana":"まいにち れんしゅう すれば、じょうずに なるに きまって いますよ。","ko":"매일 연습하면 분명 잘하게 될 거예요."},{"ja":"こんなに安い話は、嘘に決まっています。","kana":"こんなに やすい はなしは、うそに きまって います。","ko":"이렇게 싼 얘기는 거짓말이 틀림없습니다."}]},"convert":{"anime":"そんなの無理に決まってんだろ。","real":"それは少し難しいかと存じます。","note":"〜に決まってんだろ는 '당연하잖아'라고 몰아붙이는 거친 반말입니다. 고객에게 안 되는 일을 말할 때는 단정을 피하고 難しいかと存じます로 완곡하게 거절합니다."},"mission":"은퇴 후의 꿈을 〜に決まっている로 말해 보세요. 고객 은퇴 설계 상담에서 '그런 생활은 분명 즐거울 거예요'라고 공감하는 연습도 해 보세요.","missionEx":{"ja":"退職後に海の近くで暮らせたら、幸せに決まっています。","kana":"たいしょくごに うみの ちかくで くらせたら、しあわせに きまって います。","ko":"퇴직 후에 바다 근처에서 살 수 있다면 행복할 게 분명해요."},"quiz":[{"q":"「그건 거짓말이 뻔해」를 일본어로?","choices":["それは嘘のに決まってる。","それは嘘に決まってる。","それは嘘だに決まってる。"],"a":1,"why":"명사에는 に決まってる를 바로 붙입니다."},{"q":"고객에게 쓸 때 가장 알맞은 표현은?","choices":["無理に決まってんだろ。","無理に決まってる。","少し難しいかと存じます。"],"a":2,"why":"단정이 강한 に決まっている 대신 완곡한 표현을 씁니다."},{"q":"「ぐったり」의 뜻은?","choices":["녹초가 됨, 축 늘어짐","이상","왠지"],"a":0,"why":"ぐったり는 '녹초가 됨, 축 늘어짐'이라는 뜻입니다."}]},"235":{"day":235,"ep":"42","epTitle":"理非","epTitleKo":"이비","title":"〜に過ぎない — ~에 불과하다","watch":"42화 중반 · 나나미 앞에 나타난 마히토","scene":"한계에 다다른 나나미 앞에 영혼의 형태를 바꾸는 저주령 마히토가 나타난다. 마히토는 인간을 가볍게 여기는 말을 늘어놓고, 나나미는 담담하게 마지막 순간을 받아들인다.","lines":[{"who":"마히토","ja":"人間なんて、魂の形に過ぎないんだよ。","kana":"にんげん なんて、たましいの かたちに すぎないんだよ。","ko":"인간 따위는 영혼의 형태에 불과해."},{"who":"나나미","ja":"私も、仕事をこなす一人の呪術師に過ぎません。","kana":"わたしも、しごとを こなす ひとりの じゅじゅつしに すぎません。","ko":"저 역시 일을 해내는 한 명의 주술사에 불과합니다."},{"who":"마히토","ja":"君の怒りも、単なる反応に過ぎないさ。","kana":"きみの いかりも、たんなる はんのうに すぎないさ。","ko":"네 분노도 단순한 반응에 지나지 않아."}],"words":[{"w":"存在","r":"そんざい","ko":"존재"},{"w":"性質","r":"せいしつ","ko":"성질"},{"w":"思い込む","r":"おもいこむ","ko":"굳게 믿어 버리다"},{"w":"道具","r":"どうぐ","ko":"도구"},{"w":"単なる","r":"たんなる","ko":"단순한, 그저 ~인"},{"w":"理屈","r":"りくつ","ko":"이치, 논리"},{"w":"根拠","r":"こんきょ","ko":"근거"},{"w":"事実","r":"じじつ","ko":"사실"}],"grammar":{"point":"〜に過ぎない","desc":"〜に過ぎない는 '~에 불과하다, ~에 지나지 않다'라는 뜻으로, 그 이상의 의미나 가치가 없다고 낮춰 말할 때 씁니다. 주로 명사나 동사 보통형에 붙고(噂に過ぎない, 言っただけに過ぎない), 정중형은 〜に過ぎません입니다. 앞에 ただの·単なる를 함께 쓰면 '그저 ~일 뿐'이라는 느낌이 더 강해집니다. 신문·보고서 같은 딱딱한 문장에서 자주 보이며, 겸손하게 자기 역할을 말할 때도 쓸 수 있습니다.","ex":[{"ja":"それはまだ噂に過ぎません。事実を確認しましょう。","kana":"それは まだ うわさに すぎません。じじつを かくにん しましょう。","ko":"그건 아직 소문에 불과합니다. 사실을 확인합시다."},{"ja":"これは私の個人的な意見に過ぎませんが…。","kana":"これは わたしの こじんてきな いけんに すぎませんが…。","ko":"이건 제 개인적인 의견에 불과합니다만…."}]},"convert":{"anime":"そんなのただの噂だろ。","real":"それはまだ噂に過ぎないと思います。","note":"ただの噂だろ는 상대 말을 툭 잘라 버리는 반말입니다. 회의나 상담에서는 噂に過ぎないと思います로 근거가 없다는 점을 차분하게 전합니다."},"mission":"고객이 인터넷에서 본 소문(예: '보험은 다 손해다')을 묻습니다. 〜に過ぎない로 그것이 소문일 뿐이라고 차분히 답해 보세요.","missionEx":{"ja":"それはネットの噂に過ぎません。データで確認しましょう。","kana":"それは ねっとの うわさに すぎません。でーたで かくにん しましょう。","ko":"그건 인터넷 소문에 불과합니다. 데이터로 확인해 봅시다."},"quiz":[{"q":"「〜に過ぎない」의 뜻은?","choices":["~에 불과하다","~임에 틀림없다","~할 리 없다"],"a":0,"why":"그 이상의 가치가 없다고 낮춰 말하는 표현입니다."},{"q":"「그건 소문에 불과합니다」를 일본어로?","choices":["それは噂な過ぎません。","それは噂を過ぎません。","それは噂に過ぎません。"],"a":2,"why":"명사 뒤에 に過ぎません을 붙입니다."},{"q":"「存在」의 읽는 법은?","choices":["ぞんざい","そんざい","そんさい"],"a":1,"why":"存在는 そんざい, '존재'라는 뜻입니다."}]},"236":{"day":236,"ep":"42","epTitle":"理非","epTitleKo":"이비","title":"〜っこない — 절대 ~할 리 없다","watch":"42화 후반부 · 이타도리의 도착과 나나미의 마지막","scene":"이타도리가 달려왔을 때 나나미는 이미 마히토의 술식에 당한 뒤였다. 나나미는 마지막으로 이타도리에게 뒷일을 맡기고 쓰러지고, 마히토는 그 앞에서 이타도리를 조롱한다.","lines":[{"who":"나나미","ja":"虎杖君、ここから先のことは君に任せます。","kana":"いたどりくん、ここから さきの ことは きみに まかせます。","ko":"이타도리 군, 여기서부터의 일은 자네에게 맡기겠습니다."},{"who":"마히토","ja":"そんな顔したって、俺には勝てっこないよ。","kana":"そんな かお したって、おれには かてっこ ないよ。","ko":"그런 얼굴 해 봤자 나한텐 절대 못 이겨."},{"who":"이타도리","ja":"どんなに走っても、間に合いっこなかったのか…。","kana":"どんなに はしっても、まにあいっこ なかったのか…。","ko":"아무리 달려도 늦을 수밖에 없었던 건가…."}],"words":[{"w":"受け継ぐ","r":"うけつぐ","ko":"이어받다"},{"w":"引き継ぐ","r":"ひきつぐ","ko":"인계하다, 넘겨받다"},{"w":"駆けつける","r":"かけつける","ko":"급히 달려오다"},{"w":"恐らく","r":"おそらく","ko":"아마, 필시"},{"w":"ぎりぎり","r":"ぎりぎり","ko":"아슬아슬"},{"w":"既に","r":"すでに","ko":"이미"},{"w":"最期","r":"さいご","ko":"최후, 임종"},{"w":"立ち去る","r":"たちさる","ko":"떠나가다"}],"grammar":{"point":"〜っこない","desc":"〜っこない는 '절대 ~할 리 없다, ~할 수 있을 턱이 없다'라는 강한 부정 회화 표현입니다. 동사 ます형 어간에 붙입니다(勝つ→勝ちっこない, できる→できっこない, わかる→わかりっこない). 가능형과 함께 勝てっこない(이길 수 있을 리 없다)처럼 자주 씁니다. 〜わけがない보다 더 구어적이고 감정이 실린 말이라, 친한 사이나 혼잣말에서 쓰고 정식 보고·고객 응대에서는 피하는 것이 좋습니다.","ex":[{"ja":"この量じゃ、今日中に終わりっこないですよ。","kana":"この りょうじゃ、きょうじゅうに おわりっこ ないですよ。","ko":"이 양으로는 오늘 안에 절대 못 끝나요."},{"ja":"一日で覚えられっこないから、少しずつ練習しよう。","kana":"いちにちで おぼえられっこ ないから、すこしずつ れんしゅう しよう。","ko":"하루 만에 외울 수 있을 리 없으니까 조금씩 연습하자."}]},"convert":{"anime":"そんなの間に合いっこねえって。","real":"その日程ですと、間に合わない可能性が高いです。","note":"〜っこねえ는 〜っこない를 더 거칠게 말한 반말입니다. 업무에서 마감이 어렵다고 말할 때는 감정을 빼고 可能性が高いです처럼 객관적으로 전합니다."},"mission":"동료가 '이 일을 오늘 안에 다 끝낼 수 있을까?'라고 묻습니다. 친한 동료에게는 〜っこない로, 상사에게는 정중한 말로 각각 답해 보세요.","missionEx":{"ja":"正直、今日中には終わりっこないよ。明日まで手伝って。","kana":"しょうじき、きょうじゅうには おわりっこ ないよ。あしたまで てつだって。","ko":"솔직히 오늘 안에는 절대 못 끝나. 내일까지 도와줘."},"quiz":[{"q":"「できる」에 っこない를 붙인 형태는?","choices":["できっこない","できるっこない","できてっこない"],"a":0,"why":"ます형 어간 でき에 っこない를 붙입니다."},{"q":"〜っこない를 쓰기 가장 알맞은 상황은?","choices":["고객에게 보고할 때","공식 회의 발표","친한 친구와의 대화"],"a":2,"why":"감정이 실린 구어 표현이라 친한 사이에서 씁니다."},{"q":"「引き継ぐ」의 뜻은?","choices":["배웅하다","인계하다, 넘겨받다","떠나가다"],"a":1,"why":"引き継ぐ(ひきつぐ)는 '인계하다, 넘겨받다'라는 뜻입니다."}]},"237":{"day":237,"ep":"42","epTitle":"理非","epTitleKo":"이비","title":"〜かねない — ~할지도 모른다 (나쁜 결과)","watch":"42화 마지막 · 이타도리 vs 마히토, 다가오는 쿠기사키","scene":"분노한 이타도리는 마히토에게 달려들지만, 마히토는 그의 감정을 흔들며 여유를 부린다. 한편 근처에서는 쿠기사키가 이 싸움의 현장으로 다가오고 있다.","lines":[{"who":"마히토","ja":"怒りで我を忘れたら、仲間まで傷つけかねないよ？","kana":"いかりで われを わすれたら、なかま まで きずつけかねないよ？","ko":"분노로 이성을 잃으면 동료까지 다치게 할지도 몰라?"},{"who":"이타도리","ja":"冷静にならないと、また誰かを失いかねない。","kana":"れいせいに ならないと、また だれかを うしないかねない。","ko":"냉정해지지 않으면 또 누군가를 잃을지도 몰라."},{"who":"쿠기사키","ja":"放っておいたら、あいつ無茶しかねないわね。","kana":"ほうって おいたら、あいつ むちゃ しかねないわね。","ko":"내버려 두면 그 녀석 무리할지도 몰라."}],"words":[{"w":"殺意","r":"さつい","ko":"살의"},{"w":"短気","r":"たんき","ko":"성급함, 욱하는 성미"},{"w":"見失う","r":"みうしなう","ko":"놓치다, 잃다"},{"w":"無駄","r":"むだ","ko":"헛됨, 낭비"},{"w":"事故","r":"じこ","ko":"사고"},{"w":"誤解","r":"ごかい","ko":"오해"},{"w":"乱暴","r":"らんぼう","ko":"난폭함"},{"w":"用心","r":"ようじん","ko":"조심, 경계"}],"grammar":{"point":"〜かねない","desc":"〜かねない는 '~할지도 모른다, ~할 우려가 있다'라는 뜻으로, 나쁜 결과가 일어날 가능성을 경고할 때만 씁니다. 동사 ます형 어간에 붙입니다(起こる→起こりかねない, する→しかねない). 〜かもしれない와 비슷하지만 좋은 일에는 쓰지 않는다는 점이 다릅니다. 리스크를 설명하는 보험·재무 상담에서 아주 유용한 표현이고, 정중하게는 〜かねません이 됩니다.","ex":[{"ja":"油断すると、大きな事故になりかねません。","kana":"ゆだん すると、おおきな じこに なりかねません。","ko":"방심하면 큰 사고가 날 수도 있습니다."},{"ja":"説明が足りないと、お客様に誤解されかねません。","kana":"せつめいが たりないと、おきゃくさまに ごかい されかねません。","ko":"설명이 부족하면 고객에게 오해받을 우려가 있습니다."}]},"convert":{"anime":"そんなことしたら、マジでヤバいって。","real":"そうしますと、大きな損失につながりかねません。","note":"マジでヤバい는 젊은 층의 반말 은어로 무엇이 위험한지 전해지지 않습니다. 고객에게는 〜かねません으로 어떤 손해가 생길 수 있는지 구체적으로 경고합니다."},"mission":"고객이 '보험을 해지하면 어떻게 되나요?'라고 묻습니다. 생길 수 있는 불이익을 〜かねません으로 2~3가지 설명해 보세요.","missionEx":{"ja":"今解約すると、保障がなくなり、損をしかねません。","kana":"いま かいやく すると、ほしょうが なくなり、そんを しかねません。","ko":"지금 해지하시면 보장이 없어지고 손해를 보실 수도 있습니다."},"quiz":[{"q":"〜かねない를 쓸 수 없는 문장은?","choices":["事故になりかねない。","合格しかねない。","誤解されかねない。"],"a":1,"why":"かねない는 나쁜 결과에만 씁니다. 합격 같은 좋은 일에는 쓰지 않습니다."},{"q":"「する」에 かねない를 붙인 형태는?","choices":["しかねない","するかねない","さかねない"],"a":0,"why":"ます형 어간 し에 かねない를 붙입니다."},{"q":"「用心」의 뜻은?","choices":["살의","난폭함","조심, 경계"],"a":2,"why":"用心(ようじん)는 '조심, 경계'라는 뜻입니다."}]},"239":{"day":239,"ep":"43","epTitle":"理非-弐-","epTitleKo":"이비 2","title":"〜かける — ~하다 말다, ~하려던 참","watch":"43화 전반부 · 쿠기사키의 어린 시절 회상 장면","scene":"마히토의 공격을 받은 쿠기사키의 머릿속에 시골 마을에서 보낸 어린 시절과 도시로 떠나고 싶었던 마음이 스쳐 지나간다. 쿠기사키는 이타도리에게 무언가를 전하려 하고, 눈앞에서 동료를 잃을 위기에 놓인 이타도리는 크게 흔들린다.","lines":[{"who":"쿠기사키","ja":"言いかけたこと、あとでちゃんと話すからね。","kana":"いいかけた こと、あとで ちゃんと はなすからね。","ko":"하다 만 말, 나중에 제대로 해 줄게."},{"who":"이타도리","ja":"釘崎、さっき何か言いかけてたよな…？","kana":"くぎさき、さっき なにか いいかけてたよな…？","ko":"쿠기사키, 아까 뭔가 말하려고 했지…?"},{"who":"마히토","ja":"心が折れかけてるね。いい顔になってきたよ。","kana":"こころが おれかけてるね。いい かおに なって きたよ。","ko":"마음이 꺾이기 시작했네. 표정이 좋아지고 있어."}],"words":[{"w":"思わず","r":"おもわず","ko":"나도 모르게"},{"w":"寂れる","r":"さびれる","ko":"쇠퇴하다, 한산해지다"},{"w":"上京","r":"じょうきょう","ko":"상경(도쿄로 올라감)"},{"w":"大人しい","r":"おとなしい","ko":"얌전하다"},{"w":"都会","r":"とかい","ko":"도시"},{"w":"言い出す","r":"いいだす","ko":"말을 꺼내다"},{"w":"話しかける","r":"はなしかける","ko":"말을 걸다"},{"w":"飛び出す","r":"とびだす","ko":"뛰쳐나가다"}],"grammar":{"point":"〜かける","desc":"〜かける는 동사 ます형(ます를 뺀 형태)에 붙어 '~하다 말다, ~하던 도중이다, 막 ~하려 하다'라는 뜻을 나타냅니다. 言う→言いかける(말하다 말다), 読む→読みかける(읽다 말다)처럼 만듭니다. 명사로 쓰면 〜かけの(읽다 만 책 = 読みかけの本)가 됩니다. 한국어의 '~하다가 말았다'와 비슷하게, 동작이 끝나지 않은 상태라는 점이 핵심입니다.","ex":[{"ja":"書類を書きかけたまま、会議に行ってしまいました。","kana":"しょるいを かきかけた まま、かいぎに いって しまいました。","ko":"서류를 쓰다 만 채로 회의에 가 버렸습니다."},{"ja":"返事を書きかけたところで、電話が鳴りました。","kana":"へんじを かきかけた ところで、でんわが なりました。","ko":"답장을 쓰려던 참에 전화가 울렸습니다."}]},"convert":{"anime":"言いかけてやめんなよ。","real":"先ほど言いかけたことを、教えていただけますか。","note":"〜んなよ는 친구 사이의 거친 금지 표현입니다. 상대가 말을 멈췄을 때는 先ほど言いかけたこと(아까 하시려던 말씀)를 정중하게 물어보는 것이 자연스럽습니다."},"mission":"고객 상담 도중 전화가 와서 설명이 끊겼습니다. 〜かける를 써서 '아까 말씀드리다 만 내용'을 이어서 설명해 보세요.","missionEx":{"ja":"先ほど言いかけたのですが、保険の見直しについてです。","kana":"さきほど いいかけたのですが、ほけんの みなおしに ついて です。","ko":"아까 말씀드리다 말았는데, 보험 리모델링에 관한 것입니다."},"quiz":[{"q":"「읽다 만 책」을 일본어로?","choices":["読みかけの本","読むかけの本","読んだかけの本"],"a":0,"why":"ます형(読み)+かけ+の로 '읽다 만'을 만듭니다."},{"q":"「답장을 쓰려던 참에 전화가 울렸다」의 빈칸: 返事を（　）ところで、電話が鳴った。","choices":["書いてかけた","書くかけた","書きかけた"],"a":2,"why":"かける는 ます형(書き)에 붙습니다."},{"q":"「寂れる」의 뜻은?","choices":["쇠퇴하다, 한산해지다","나도 모르게","뛰쳐나가다"],"a":0,"why":"寂れる(さびれる)는 '쇠퇴하다, 한산해지다'라는 뜻입니다."}]}});
